window.ExtraBibleBooks=window.ExtraBibleBooks||{};window.ExtraBibleBooks["HAG"]={"book":"HAG","editions":{"hbo-source":[[1,1,"בִּ⁠שְׁנַ֤ת שְׁתַּ֨יִם֙ לְ⁠דָרְיָ֣וֶשׁ הַ⁠מֶּ֔לֶךְ בַּ⁠חֹ֨דֶשׁ֙ הַ⁠שִּׁשִּׁ֔י בְּ⁠י֥וֹם אֶחָ֖ד לַ⁠חֹ֑דֶשׁ הָיָ֨ה דְבַר־יְהוָ֜ה בְּ⁠יַד־חַגַּ֣י הַ⁠נָּבִ֗יא אֶל־זְרֻבָּבֶ֤ל בֶּן־שְׁאַלְתִּיאֵל֙ פַּחַ֣ת יְהוּדָ֔ה וְ⁠אֶל־יְהוֹשֻׁ֧עַ בֶּן־יְהוֹצָדָ֛ק הַ⁠כֹּהֵ֥ן הַ⁠גָּד֖וֹל לֵ⁠אמֹֽר׃","bi̇⁠şĕ̌na֤ţ şĕ̌ţȧ֨yim֙ lĕ⁠dárĕyá֣weş̌ ha⁠mė֔lekĕ bȧ⁠ẖò֨deş̌֙ ha⁠şi̇̌şi̇̌֔y bĕ̇⁠y֥wòm ʼeẖá֖d la⁠ẖò֑deş̌ háyá֨h dĕbar-yĕhwá֜h bĕ̇⁠yad-ẖagȧ֣y ha⁠ná̇bi֗yʼ ʼel-zĕrubá̇be֤l bėn-şĕ̌ʼalĕţi̇yʼél֙ pȧẖa֣ţ yĕhẇdá֔h wĕ⁠ʼel-yĕhwòşǔ֧ʻa bėn-yĕhwòẕádá֛q ha⁠kò̇hé֥n ha⁠gá̇d֖wòl lé⁠ʼmòֽr׃"],[1,2,"כֹּ֥ה אָמַ֛ר יְהוָ֥ה צְבָא֖וֹת לֵ⁠אמֹ֑ר הָ⁠עָ֤ם הַ⁠זֶּה֙ אָֽמְר֔וּ לֹ֥א עֶת־בֹּ֛א עֶת־בֵּ֥ית יְהוָ֖ה לְ⁠הִבָּנֽוֹת׃פ","kò֥̇h ʼáma֛r yĕhwá֥h ẕĕbáʼ֖wòţ lé⁠ʼmò֑r há⁠ʻá֤m ha⁠zėh֙ ʼáֽmĕr֔ẇ lò֥ʼ ʻeţ-bò֛̇ʼ ʻeţ-bé֥̇yţ yĕhwá֖h lĕ⁠hibá̇nֽwòţ׃p"],[1,3,"וַֽ⁠יְהִי֙ דְּבַר־יְהוָ֔ה בְּ⁠יַד־חַגַּ֥י הַ⁠נָּבִ֖יא לֵ⁠אמֹֽר׃","waֽ⁠yĕhiy֙ dĕ̇bar-yĕhwá֔h bĕ̇⁠yad-ẖagȧ֥y ha⁠ná̇bi֖yʼ lé⁠ʼmòֽr׃"],[1,4,"הַ⁠עֵ֤ת לָ⁠כֶם֙ אַתֶּ֔ם לָ⁠שֶׁ֖בֶת בְּ⁠בָתֵּי⁠כֶ֣ם סְפוּנִ֑ים וְ⁠הַ⁠בַּ֥יִת הַ⁠זֶּ֖ה חָרֵֽב׃","ha⁠ʻé֤ţ lá⁠kem֙ ʼaţė֔m lá⁠şě֖beţ bĕ̇⁠báţé̇y⁠ke֣m sĕpẇni֑ym wĕ⁠ha⁠bȧ֥yiţ ha⁠zė֖h ẖáréֽb׃"],[1,5,"וְ⁠עַתָּ֕ה כֹּ֥ה אָמַ֖ר יְהוָ֣ה צְבָא֑וֹת שִׂ֥ימוּ לְבַבְ⁠כֶ֖ם עַל־דַּרְכֵי⁠כֶֽם׃","wĕ⁠ʻaţá̇֕h kò֥̇h ʼáma֖r yĕhwá֣h ẕĕbáʼ֑wòţ şî֥ymẇ lĕbabĕ⁠ke֖m ʻal-dȧrĕkéy⁠keֽm׃"],[1,6,"זְרַעְתֶּ֨ם הַרְבֵּ֜ה וְ⁠הָבֵ֣א מְעָ֗ט אָכ֤וֹל וְ⁠אֵין־לְ⁠שָׂבְעָה֙ שָׁת֣וֹ וְ⁠אֵין־לְ⁠שָׁכְרָ֔ה לָב֖וֹשׁ וְ⁠אֵין־לְ⁠חֹ֣ם ל֑⁠וֹ וְ⁠הַ֨⁠מִּשְׂתַּכֵּ֔ר מִשְׂתַּכֵּ֖ר אֶל־צְר֥וֹר נָקֽוּב׃פ","zĕraʻĕţė֨m harĕbé̇֜h wĕ⁠hábé֣ʼ mĕʻá֗t ʼák֤wòl wĕ⁠ʼéyn-lĕ⁠şá̂bĕʻáh֙ şá̌ţ֣wò wĕ⁠ʼéyn-lĕ⁠şá̌kĕrá֔h láb֖wòş̌ wĕ⁠ʼéyn-lĕ⁠ẖò֣m l֑⁠wò wĕ⁠ha֨⁠mi̇şĕ̂ţȧké̇֔r mişĕ̂ţȧké֖̇r ʼel-ẕĕr֥wòr náqֽẇb׃p"],[1,7,"כֹּ֥ה אָמַ֖ר יְהוָ֣ה צְבָא֑וֹת שִׂ֥ימוּ לְבַבְ⁠כֶ֖ם עַל־דַּרְכֵי⁠כֶֽם׃","kò֥̇h ʼáma֖r yĕhwá֣h ẕĕbáʼ֑wòţ şî֥ymẇ lĕbabĕ⁠ke֖m ʻal-dȧrĕkéy⁠keֽm׃"],[1,8,"עֲל֥וּ הָ⁠הָ֛ר וַ⁠הֲבֵאתֶ֥ם עֵ֖ץ וּ⁠בְנ֣וּ הַ⁠בָּ֑יִת וְ⁠אֶרְצֶה־בּ֥⁠וֹ ו⁠אכבד אָמַ֥ר יְהוָֽה׃","ʻàl֥ẇ há⁠há֛r wa⁠hàbéʼţe֥m ʻé֖ẕ ẇ⁠bĕn֣ẇ ha⁠bá֑̇yiţ wĕ⁠ʼerĕẕeh-ḃ֥⁠wò w⁠ʼkbd ʼáma֥r yĕhwáֽh׃"],[1,9,"פָּנֹ֤ה אֶל־הַרְבֵּה֙ וְ⁠הִנֵּ֣ה לִ⁠מְעָ֔ט וַ⁠הֲבֵאתֶ֥ם הַ⁠בַּ֖יִת וְ⁠נָפַ֣חְתִּי ב֑⁠וֹ יַ֣עַן מֶ֗ה נְאֻם֙ יְהוָ֣ה צְבָא֔וֹת יַ֗עַן בֵּיתִ⁠י֙ אֲשֶׁר־ה֣וּא חָרֵ֔ב וְ⁠אַתֶּ֥ם רָצִ֖ים אִ֥ישׁ לְ⁠בֵיתֽ⁠וֹ׃","pá̇nò֤h ʼel-harĕbé̇h֙ wĕ⁠hiné֣̇h li⁠mĕʻá֔t wa⁠hàbéʼţe֥m ha⁠bȧ֖yiţ wĕ⁠nápa֣ẖĕţi̇y b֑⁠wò ya֣ʻan me֗h nĕʼum֙ yĕhwá֣h ẕĕbáʼ֔wòţ ya֗ʻan bé̇yţi⁠y֙ ʼàşěr-h֣ẇʼ ẖáré֔b wĕ⁠ʼaţė֥m ráẕi֖ym ʼi֥yş̌ lĕ⁠béyţֽ⁠wò׃"],[1,10,"עַל־כֵּ֣ן עֲלֵי⁠כֶ֔ם כָּלְא֥וּ שָמַ֖יִם מִ⁠טָּ֑ל וְ⁠הָ⁠אָ֖רֶץ כָּלְאָ֥ה יְבוּלָֽ⁠הּ׃","ʻal-ké֣̇n ʻàléy⁠ke֔m ká̇lĕʼ֥ẇ şáma֖yim mi⁠tá֑̇l wĕ⁠há⁠ʼá֖reẕ ká̇lĕʼá֥h yĕbẇláֽ⁠ḣ׃"],[1,11,"וָ⁠אֶקְרָ֨א חֹ֜רֶב עַל־הָ⁠אָ֣רֶץ וְ⁠עַל־הֶ⁠הָרִ֗ים וְ⁠עַל־הַ⁠דָּגָן֙ וְ⁠עַל־הַ⁠תִּיר֣וֹשׁ וְ⁠עַל־הַ⁠יִּצְהָ֔ר וְ⁠עַ֛ל אֲשֶׁ֥ר תּוֹצִ֖יא הָ⁠אֲדָמָ֑ה וְ⁠עַל־הָֽ⁠אָדָם֙ וְ⁠עַל־הַ⁠בְּהֵמָ֔ה וְ⁠עַ֖ל כָּל־יְגִ֥יעַ כַּפָּֽיִם׃ס","wá⁠ʼeqĕrá֨ʼ ẖò֜reb ʻal-há⁠ʼá֣reẕ wĕ⁠ʻal-he⁠hári֗ym wĕ⁠ʻal-ha⁠dá̇gán֙ wĕ⁠ʻal-ha⁠ţi̇yr֣wòş̌ wĕ⁠ʻal-ha⁠yi̇ẕĕhá֔r wĕ⁠ʻa֛l ʼàşě֥r ţ̇wòẕi֖yʼ há⁠ʼàdámá֑h wĕ⁠ʻal-háֽ⁠ʼádám֙ wĕ⁠ʻal-ha⁠bĕ̇hémá֔h wĕ⁠ʻa֖l ká̇l-yĕgi֥yʻa kȧpáֽ̇yim׃s"],[1,12,"וַ⁠יִּשְׁמַ֣ע זְרֻבָּבֶ֣ל ׀ בֶּֽן־שַׁלְתִּיאֵ֡ל וִ⁠יהוֹשֻׁ֣עַ בֶּן־יְהוֹצָדָק֩ הַ⁠כֹּהֵ֨ן הַ⁠גָּד֜וֹל וְ⁠כֹ֣ל ׀ שְׁאֵרִ֣ית הָ⁠עָ֗ם בְּ⁠קוֹל֙ יְהוָ֣ה אֱלֹֽהֵי⁠הֶ֔ם וְ⁠עַל־דִּבְרֵי֙ חַגַּ֣י הַ⁠נָּבִ֔יא כַּ⁠אֲשֶׁ֥ר שְׁלָח֖⁠וֹ יְהוָ֣ה אֱלֹהֵי⁠הֶ֑ם וַ⁠יִּֽירְא֥וּ הָ⁠עָ֖ם מִ⁠פְּנֵ֥י יְהוָֽה׃","wa⁠yi̇şĕ̌ma֣ʻ zĕrubá̇be֣l ׀ bėֽn-şǎlĕţi̇yʼé֡l wi⁠yhwòşǔ֣ʻa bėn-yĕhwòẕádáq֩ ha⁠kò̇hé֨n ha⁠gá̇d֜wòl wĕ⁠kò֣l ׀ şĕ̌ʼéri֣yţ há⁠ʻá֗m bĕ̇⁠qwòl֙ yĕhwá֣h ʼèlòֽhéy⁠he֔m wĕ⁠ʻal-di̇bĕréy֙ ẖagȧ֣y ha⁠ná̇bi֔yʼ kȧ⁠ʼàşě֥r şĕ̌láẖ֖⁠wò yĕhwá֣h ʼèlòhéy⁠he֑m wa⁠yiֽ̇yrĕʼ֥ẇ há⁠ʻá֖m mi⁠pĕ̇né֥y yĕhwáֽh׃"],[1,13,"וַ֠⁠יֹּאמֶר חַגַּ֞י מַלְאַ֧ךְ יְהוָ֛ה בְּ⁠מַלְאֲכ֥וּת יְהוָ֖ה לָ⁠עָ֣ם לֵ⁠אמֹ֑ר אֲנִ֥י אִתְּ⁠כֶ֖ם נְאֻם־יְהוָֽה׃","wa֠⁠yò̇ʼmer ẖagȧ֞y malĕʼa֧kĕ yĕhwá֛h bĕ̇⁠malĕʼàk֥ẇţ yĕhwá֖h lá⁠ʻá֣m lé⁠ʼmò֑r ʼàni֥y ʼiţĕ̇⁠ke֖m nĕʼum-yĕhwáֽh׃"],[1,14,"וַ⁠יָּ֣עַר יְהוָ֡ה אֶת־רוּחַ֩ זְרֻבָּבֶ֨ל בֶּן־שַׁלְתִּיאֵ֜ל פַּחַ֣ת יְהוּדָ֗ה וְ⁠אֶת־ר֨וּחַ֙ יְהוֹשֻׁ֤עַ בֶּן־יְהוֹצָדָק֙ הַ⁠כֹּהֵ֣ן הַ⁠גָּד֔וֹל וְֽ⁠אֶת־ר֔וּחַ כֹּ֖ל שְׁאֵרִ֣ית הָ⁠עָ֑ם וַ⁠יָּבֹ֨אוּ֙ וַ⁠יַּעֲשׂ֣וּ מְלָאכָ֔ה בְּ⁠בֵית־יְהוָ֥ה צְבָא֖וֹת אֱלֹהֵי⁠הֶֽם׃פ","wa⁠yá֣̇ʻar yĕhwá֡h ʼeţ-rẇẖa֩ zĕrubá̇be֨l bėn-şǎlĕţi̇yʼé֜l pȧẖa֣ţ yĕhẇdá֗h wĕ⁠ʼeţ-r֨ẇẖa֙ yĕhwòşǔ֤ʻa bėn-yĕhwòẕádáq֙ ha⁠kò̇hé֣n ha⁠gá̇d֔wòl wĕֽ⁠ʼeţ-r֔ẇẖa kò֖̇l şĕ̌ʼéri֣yţ há⁠ʻá֑m wa⁠yá̇bò֨ʼẇ֙ wa⁠yȧʻàş֣̂ẇ mĕláʼká֔h bĕ̇⁠béyţ-yĕhwá֥h ẕĕbáʼ֖wòţ ʼèlòhéy⁠heֽm׃p"],[1,15,"בְּ⁠י֨וֹם עֶשְׂרִ֧ים וְ⁠אַרְבָּעָ֛ה לַ⁠חֹ֖דֶשׁ בַּ⁠שִּׁשִּׁ֑י בִּ⁠שְׁנַ֥ת שְׁתַּ֖יִם לְ⁠דָרְיָ֥וֶשׁ הַ⁠מֶּֽלֶךְ׃","bĕ̇⁠y֨wòm ʻeşĕ̂ri֧ym wĕ⁠ʼarĕbá̇ʻá֛h la⁠ẖò֖deş̌ bȧ⁠şi̇̌şi֑̇̌y bi̇⁠şĕ̌na֥ţ şĕ̌ţȧ֖yim lĕ⁠dárĕyá֥weş̌ ha⁠mėֽlekĕ׃"],[2,1,"בַּ⁠שְּׁבִיעִ֕י בְּ⁠עֶשְׂרִ֥ים וְ⁠אֶחָ֖ד לַ⁠חֹ֑דֶשׁ הָיָה֙ דְּבַר־יְהוָ֔ה בְּ⁠יַד־חַגַּ֥י הַ⁠נָּבִ֖יא לֵ⁠אמֹֽר׃","bȧ⁠şĕ̇̌biyʻi֕y bĕ̇⁠ʻeşĕ̂ri֥ym wĕ⁠ʼeẖá֖d la⁠ẖò֑deş̌ háyáh֙ dĕ̇bar-yĕhwá֔h bĕ̇⁠yad-ẖagȧ֥y ha⁠ná̇bi֖yʼ lé⁠ʼmòֽr׃"],[2,2,"אֱמָר־נָ֗א אֶל־זְרֻבָּבֶ֤ל בֶּן־שַׁלְתִּיאֵל֙ פַּחַ֣ת יְהוּדָ֔ה וְ⁠אֶל־יְהוֹשֻׁ֥עַ בֶּן־יְהוֹצָדָ֖ק הַ⁠כֹּהֵ֣ן הַ⁠גָּד֑וֹל וְ⁠אֶל־שְׁאֵרִ֥ית הָ⁠עָ֖ם לֵ⁠אמֹֽר׃","ʼèmár-ná֗ʼ ʼel-zĕrubá̇be֤l bėn-şǎlĕţi̇yʼél֙ pȧẖa֣ţ yĕhẇdá֔h wĕ⁠ʼel-yĕhwòşǔ֥ʻa bėn-yĕhwòẕádá֖q ha⁠kò̇hé֣n ha⁠gá̇d֑wòl wĕ⁠ʼel-şĕ̌ʼéri֥yţ há⁠ʻá֖m lé⁠ʼmòֽr׃"],[2,3,"מִ֤י בָ⁠כֶם֙ הַ⁠נִּשְׁאָ֔ר אֲשֶׁ֤ר רָאָה֙ אֶת־הַ⁠בַּ֣יִת הַ⁠זֶּ֔ה בִּ⁠כְבוֹד֖⁠וֹ הָ⁠רִאשׁ֑וֹן וּ⁠מָ֨ה אַתֶּ֜ם רֹאִ֤ים אֹת⁠וֹ֙ עַ֔תָּה הֲ⁠ל֥וֹא כָמֹ֛⁠הוּ כְּ⁠אַ֖יִן בְּ⁠עֵינֵי⁠כֶֽם׃","mi֤y bá⁠kem֙ ha⁠ni̇şĕ̌ʼá֔r ʼàşě֤r ráʼáh֙ ʼeţ-ha⁠bȧ֣yiţ ha⁠zė֔h bi̇⁠kĕbwòd֖⁠wò há⁠riʼş֑̌wòn ẇ⁠má֨h ʼaţė֜m ròʼi֤ym ʼòţ⁠wò֙ ʻa֔ţá̇h hà⁠l֥wòʼ kámò֛⁠hẇ kĕ̇⁠ʼa֖yin bĕ̇⁠ʻéynéy⁠keֽm׃"],[2,4,"וְ⁠עַתָּ֣ה חֲזַ֣ק זְרֻבָּבֶ֣ל ׀ נְאֻם־יְהוָ֡ה וַ⁠חֲזַ֣ק יְהוֹשֻׁ֣עַ בֶּן־יְהוֹצָדָק֩ הַ⁠כֹּהֵ֨ן הַ⁠גָּד֜וֹל וַ⁠חֲזַ֨ק כָּל־עַ֥ם הָ⁠אָ֛רֶץ נְאֻם־יְהוָ֖ה וַֽ⁠עֲשׂ֑וּ כִּֽי־אֲנִ֣י אִתְּ⁠כֶ֔ם נְאֻ֖ם יְהוָ֥ה צְבָאֽוֹת׃","wĕ⁠ʻaţá֣̇h ẖàza֣q zĕrubá̇be֣l ׀ nĕʼum-yĕhwá֡h wa⁠ẖàza֣q yĕhwòşǔ֣ʻa bėn-yĕhwòẕádáq֩ ha⁠kò̇hé֨n ha⁠gá̇d֜wòl wa⁠ẖàza֨q ká̇l-ʻa֥m há⁠ʼá֛reẕ nĕʼum-yĕhwá֖h waֽ⁠ʻàş֑̂ẇ kiֽ̇y-ʼàni֣y ʼiţĕ̇⁠ke֔m nĕʼu֖m yĕhwá֥h ẕĕbáʼֽwòţ׃"],[2,5,"אֶֽת־הַ⁠דָּבָ֞ר אֲשֶׁר־כָּרַ֤תִּי אִתְּ⁠כֶם֙ בְּ⁠צֵאתְ⁠כֶ֣ם מִ⁠מִּצְרַ֔יִם וְ⁠רוּחִ֖⁠י עֹמֶ֣דֶת בְּ⁠תוֹכְ⁠כֶ֑ם אַל־תִּירָֽאוּ׃ס","ʼeֽţ-ha⁠dá̇bá֞r ʼàşěr-ká̇ra֤ţi̇y ʼiţĕ̇⁠kem֙ bĕ̇⁠ẕéʼţĕ⁠ke֣m mi⁠mi̇ẕĕra֔yim wĕ⁠rẇẖi֖⁠y ʻòme֣deţ bĕ̇⁠ţwòkĕ⁠ke֑m ʼal-ţi̇yráֽʼẇ׃s"],[2,6,"כִּ֣י כֹ֤ה אָמַר֙ יְהוָ֣ה צְבָא֔וֹת ע֥וֹד אַחַ֖ת מְעַ֣ט הִ֑יא וַ⁠אֲנִ֗י מַרְעִישׁ֙ אֶת־הַ⁠שָּׁמַ֣יִם וְ⁠אֶת־הָ⁠אָ֔רֶץ וְ⁠אֶת־הַ⁠יָּ֖ם וְ⁠אֶת־הֶ⁠חָרָבָֽה׃","ki֣̇y kò֤h ʼámar֙ yĕhwá֣h ẕĕbáʼ֔wòţ ʻ֥wòd ʼaẖa֖ţ mĕʻa֣t hi֑yʼ wa⁠ʼàni֗y marĕʻiyş̌֙ ʼeţ-ha⁠şá̇̌ma֣yim wĕ⁠ʼeţ-há⁠ʼá֔reẕ wĕ⁠ʼeţ-ha⁠yá֖̇m wĕ⁠ʼeţ-he⁠ẖárábáֽh׃"],[2,7,"וְ⁠הִרְעַשְׁתִּי֙ אֶת־כָּל־הַ⁠גּוֹיִ֔ם וּ⁠בָ֖אוּ חֶמְדַּ֣ת כָּל־הַ⁠גּוֹיִ֑ם וּ⁠מִלֵּאתִ֞י אֶת־הַ⁠בַּ֤יִת הַ⁠זֶּה֙ כָּב֔וֹד אָמַ֖ר יְהוָ֥ה צְבָאֽוֹת׃","wĕ⁠hirĕʻaşĕ̌ţi̇y֙ ʼeţ-ká̇l-ha⁠ġwòyi֔m ẇ⁠bá֖ʼẇ ẖemĕdȧ֣ţ ká̇l-ha⁠ġwòyi֑m ẇ⁠milé̇ʼţi֞y ʼeţ-ha⁠bȧ֤yiţ ha⁠zėh֙ ká̇b֔wòd ʼáma֖r yĕhwá֥h ẕĕbáʼֽwòţ׃"],[2,8,"לִ֥⁠י הַ⁠כֶּ֖סֶף וְ⁠לִ֣⁠י הַ⁠זָּהָ֑ב נְאֻ֖ם יְהוָ֥ה צְבָאֽוֹת׃","li֥⁠y ha⁠kė֖sep wĕ⁠li֣⁠y ha⁠zá̇há֑b nĕʼu֖m yĕhwá֥h ẕĕbáʼֽwòţ׃"],[2,9,"גָּד֣וֹל יִֽהְיֶ֡ה כְּבוֹד֩ הַ⁠בַּ֨יִת הַ⁠זֶּ֤ה הָ⁠אַֽחֲרוֹן֙ מִן־הָ֣⁠רִאשׁ֔וֹן אָמַ֖ר יְהוָ֣ה צְבָא֑וֹת וּ⁠בַ⁠מָּק֤וֹם הַ⁠זֶּה֙ אֶתֵּ֣ן שָׁל֔וֹם נְאֻ֖ם יְהוָ֥ה צְבָאֽוֹת׃פ","gá̇d֣wòl yiֽhĕye֡h kĕ̇bwòd֩ ha⁠bȧ֨yiţ ha⁠zė֤h há⁠ʼaֽẖàrwòn֙ min-há֣⁠riʼş̌֔wòn ʼáma֖r yĕhwá֣h ẕĕbáʼ֑wòţ ẇ⁠ba⁠má̇q֤wòm ha⁠zėh֙ ʼeţé֣̇n şá̌l֔wòm nĕʼu֖m yĕhwá֥h ẕĕbáʼֽwòţ׃p"],[2,10,"בְּ⁠עֶשְׂרִ֤ים וְ⁠אַרְבָּעָה֙ לַ⁠תְּשִׁיעִ֔י בִּ⁠שְׁנַ֥ת שְׁתַּ֖יִם לְ⁠דָרְיָ֑וֶשׁ הָיָה֙ דְּבַר־יְהוָ֔ה אֶל־חַגַּ֥י הַ⁠נָּבִ֖יא לֵ⁠אמֹֽר׃","bĕ̇⁠ʻeşĕ̂ri֤ym wĕ⁠ʼarĕbá̇ʻáh֙ la⁠ţĕ̇şǐyʻi֔y bi̇⁠şĕ̌na֥ţ şĕ̌ţȧ֖yim lĕ⁠dárĕyá֑weş̌ háyáh֙ dĕ̇bar-yĕhwá֔h ʼel-ẖagȧ֥y ha⁠ná̇bi֖yʼ lé⁠ʼmòֽr׃"],[2,11,"כֹּ֥ה אָמַ֖ר יְהוָ֣ה צְבָא֑וֹת שְׁאַל־נָ֧א אֶת־הַ⁠כֹּהֲנִ֛ים תּוֹרָ֖ה לֵ⁠אמֹֽר׃","kò֥̇h ʼáma֖r yĕhwá֣h ẕĕbáʼ֑wòţ şĕ̌ʼal-ná֧ʼ ʼeţ-ha⁠kò̇hàni֛ym ţ̇wòrá֖h lé⁠ʼmòֽr׃"],[2,12,"הֵ֣ן ׀ יִשָּׂא־אִ֨ישׁ בְּשַׂר־קֹ֜דֶשׁ בִּ⁠כְנַ֣ף בִּגְד֗⁠וֹ וְ⁠נָגַ֣ע בִּ֠⁠כְנָפ⁠וֹ אֶל־הַ⁠לֶּ֨חֶם וְ⁠אֶל־הַ⁠נָּזִ֜יד וְ⁠אֶל־הַ⁠יַּ֧יִן וְ⁠אֶל־שֶׁ֛מֶן וְ⁠אֶל־כָּל־מַאֲכָ֖ל הֲ⁠יִקְדָּ֑שׁ וַ⁠יַּעֲנ֧וּ הַ⁠כֹּהֲנִ֛ים וַ⁠יֹּאמְר֖וּ לֹֽא׃","hé֣n ׀ yişá̇̂ʼ-ʼi֨yş̌ bĕ̇şâr-qò֜deş̌ bi̇⁠kĕna֣p bi̇gĕd֗⁠wò wĕ⁠nága֣ʻ bi̇֠⁠kĕnáp⁠wò ʼel-ha⁠lė֨ẖem wĕ⁠ʼel-ha⁠ná̇zi֜yd wĕ⁠ʼel-ha⁠yȧ֧yin wĕ⁠ʼel-şě֛men wĕ⁠ʼel-ká̇l-maʼàká֖l hà⁠yiqĕdá֑̇ş̌ wa⁠yȧʻàn֧ẇ ha⁠kò̇hàni֛ym wa⁠yò̇ʼmĕr֖ẇ lòֽʼ׃"],[2,13,"וַ⁠יֹּ֣אמֶר חַגַּ֔י אִם־יִגַּ֧ע טְמֵא־נֶ֛פֶשׁ בְּ⁠כָל־אֵ֖לֶּה הֲ⁠יִטְמָ֑א וַ⁠יַּעֲנ֧וּ הַ⁠כֹּהֲנִ֛ים וַ⁠יֹּאמְר֖וּ יִטְמָֽא׃","wa⁠yò֣̇ʼmer ẖagȧ֔y ʼim-yigȧ֧ʻ tĕméʼ-ne֛peş̌ bĕ̇⁠kál-ʼé֖lėh hà⁠yitĕmá֑ʼ wa⁠yȧʻàn֧ẇ ha⁠kò̇hàni֛ym wa⁠yò̇ʼmĕr֖ẇ yitĕmáֽʼ׃"],[2,14,"וַ⁠יַּ֨עַן חַגַּ֜י וַ⁠יֹּ֗אמֶר כֵּ֣ן הָֽ⁠עָם־הַ֠⁠זֶּה וְ⁠כֵן־הַ⁠גּ֨וֹי הַ⁠זֶּ֤ה לְ⁠פָנַ⁠י֙ נְאֻם־יְהוָ֔ה וְ⁠כֵ֖ן כָּל־מַעֲשֵׂ֣ה יְדֵי⁠הֶ֑ם וַ⁠אֲשֶׁ֥ר יַקְרִ֛יבוּ שָׁ֖ם טָמֵ֥א הֽוּא׃","wa⁠yȧ֨ʻan ẖagȧ֜y wa⁠yò̇֗ʼmer ké֣̇n háֽ⁠ʻám-ha֠⁠zėh wĕ⁠kén-ha⁠ġ֨wòy ha⁠zė֤h lĕ⁠pána⁠y֙ nĕʼum-yĕhwá֔h wĕ⁠ké֖n ká̇l-maʻàşé֣̂h yĕdéy⁠he֑m wa⁠ʼàşě֥r yaqĕri֛ybẇ şá֖̌m támé֥ʼ hֽẇʼ׃"],[2,15,"וְ⁠עַתָּה֙ שִֽׂימוּ־נָ֣א לְבַבְ⁠כֶ֔ם מִן־הַ⁠יּ֥וֹם הַ⁠זֶּ֖ה וָ⁠מָ֑עְלָ⁠ה מִ⁠טֶּ֧רֶם שֽׂוּם־אֶ֛בֶן אֶל־אֶ֖בֶן בְּ⁠הֵיכַ֥ל יְהוָֽה׃","wĕ⁠ʻaţá̇h֙ şîֽymẇ-ná֣ʼ lĕbabĕ⁠ke֔m min-ha⁠ẏ֥wòm ha⁠zė֖h wá⁠má֑ʻĕlá⁠h mi⁠tė֧rem şֽ̂ẇm-ʼe֛ben ʼel-ʼe֖ben bĕ̇⁠héyka֥l yĕhwáֽh׃"],[2,16,"מִֽ⁠הְיוֹתָ֥⁠ם בָּא֙ אֶל־עֲרֵמַ֣ת עֶשְׂרִ֔ים וְ⁠הָיְתָ֖ה עֲשָׂרָ֑ה בָּ֣א אֶל־הַ⁠יֶּ֗קֶב לַ⁠חְשֹׂף֙ חֲמִשִּׁ֣ים פּוּרָ֔ה וְ⁠הָיְתָ֖ה עֶשְׂרִֽים׃","miֽ⁠hĕywòţá֥⁠m bá̇ʼ֙ ʼel-ʻàréma֣ţ ʻeşĕ̂ri֔ym wĕ⁠háyĕţá֖h ʻàşá̂rá֑h bá֣̇ʼ ʼel-ha⁠yė֗qeb la⁠ẖĕşò̂p֙ ẖàmişi֣̇̌ym ṗẇrá֔h wĕ⁠háyĕţá֖h ʻeşĕ̂riֽym׃"],[2,17,"הִכֵּ֨יתִי אֶתְ⁠כֶ֜ם בַּ⁠שִּׁדָּפ֤וֹן וּ⁠בַ⁠יֵּֽרָקוֹן֙ וּ⁠בַ⁠בָּרָ֔ד אֵ֖ת כָּל־מַעֲשֵׂ֣ה יְדֵי⁠כֶ֑ם וְ⁠אֵין־אֶתְ⁠כֶ֥ם אֵלַ֖⁠י נְאֻם־יְהוָֽה׃","hiké̇֨yţiy ʼeţĕ⁠ke֜m bȧ⁠şi̇̌dá̇p֤wòn ẇ⁠ba⁠yéֽ̇ráqwòn֙ ẇ⁠ba⁠bá̇rá֔d ʼé֖ţ ká̇l-maʻàşé֣̂h yĕdéy⁠ke֑m wĕ⁠ʼéyn-ʼeţĕ⁠ke֥m ʼéla֖⁠y nĕʼum-yĕhwáֽh׃"],[2,18,"שִׂימוּ־נָ֣א לְבַבְ⁠כֶ֔ם מִן־הַ⁠יּ֥וֹם הַ⁠זֶּ֖ה וָ⁠מָ֑עְלָ⁠ה מִ⁠יּוֹם֩ עֶשְׂרִ֨ים וְ⁠אַרְבָּעָ֜ה לַ⁠תְּשִׁיעִ֗י לְ⁠מִן־הַ⁠יּ֛וֹם אֲשֶׁר־יֻסַּ֥ד הֵֽיכַל־יְהוָ֖ה שִׂ֥ימוּ לְבַבְ⁠כֶֽם׃","şîymẇ-ná֣ʼ lĕbabĕ⁠ke֔m min-ha⁠ẏ֥wòm ha⁠zė֖h wá⁠má֑ʻĕlá⁠h mi⁠ẏwòm֩ ʻeşĕ̂ri֨ym wĕ⁠ʼarĕbá̇ʻá֜h la⁠ţĕ̇şǐyʻi֗y lĕ⁠min-ha⁠ẏ֛wòm ʼàşěr-yusȧ֥d héֽykal-yĕhwá֖h şî֥ymẇ lĕbabĕ⁠keֽm׃"],[2,19,"הַ⁠ע֤וֹד הַ⁠זֶּ֨רַע֙ בַּ⁠מְּגוּרָ֔ה וְ⁠עַד־הַ⁠גֶּ֨פֶן וְ⁠הַ⁠תְּאֵנָ֧ה וְ⁠הָ⁠רִמּ֛וֹן וְ⁠עֵ֥ץ הַ⁠זַּ֖יִת לֹ֣א נָשָׂ֑א מִן־הַ⁠יּ֥וֹם הַ⁠זֶּ֖ה אֲבָרֵֽךְ׃ס","ha⁠ʻ֤wòd ha⁠zė֨raʻ֙ bȧ⁠mĕ̇gẇrá֔h wĕ⁠ʻad-ha⁠gė֨pen wĕ⁠ha⁠ţĕ̇ʼéná֧h wĕ⁠há⁠riṁ֛wòn wĕ⁠ʻé֥ẕ ha⁠zȧ֖yiţ lò֣ʼ náşá֑̂ʼ min-ha⁠ẏ֥wòm ha⁠zė֖h ʼàbáréֽkĕ׃s"],[2,20,"וַ⁠יְהִ֨י דְבַר־יְהוָ֤ה ׀ שֵׁנִית֙ אֶל־חַגַּ֔י בְּ⁠עֶשְׂרִ֧ים וְ⁠אַרְבָּעָ֛ה לַ⁠חֹ֖דֶשׁ לֵ⁠אמֹֽר׃","wa⁠yĕhi֨y dĕbar-yĕhwá֤h ׀ şé̌niyţ֙ ʼel-ẖagȧ֔y bĕ̇⁠ʻeşĕ̂ri֧ym wĕ⁠ʼarĕbá̇ʻá֛h la⁠ẖò֖deş̌ lé⁠ʼmòֽr׃"],[2,21,"אֱמֹ֕ר אֶל־זְרֻבָּבֶ֥ל פַּֽחַת־יְהוּדָ֖ה לֵ⁠אמֹ֑ר אֲנִ֣י מַרְעִ֔ישׁ אֶת־הַ⁠שָּׁמַ֖יִם וְ⁠אֶת־הָ⁠אָֽרֶץ׃","ʼèmò֕r ʼel-zĕrubá̇be֥l pȧֽẖaţ-yĕhẇdá֖h lé⁠ʼmò֑r ʼàni֣y marĕʻi֔yş̌ ʼeţ-ha⁠şá̇̌ma֖yim wĕ⁠ʼeţ-há⁠ʼáֽreẕ׃"],[2,22,"וְ⁠הָֽפַכְתִּי֙ כִּסֵּ֣א מַמְלָכ֔וֹת וְ⁠הִ֨שְׁמַדְתִּ֔י חֹ֖זֶק מַמְלְכ֣וֹת הַ⁠גּוֹיִ֑ם וְ⁠הָפַכְתִּ֤י מֶרְכָּבָה֙ וְ⁠רֹ֣כְבֶ֔י⁠הָ וְ⁠יָרְד֤וּ סוּסִים֙ וְ⁠רֹ֣כְבֵי⁠הֶ֔ם אִ֖ישׁ בְּ⁠חֶ֥רֶב אָחִֽי⁠ו׃","wĕ⁠háֽpakĕţi̇y֙ ki̇sé֣̇ʼ mamĕlák֔wòţ wĕ⁠hi֨şĕ̌madĕţi̇֔y ẖò֖zeq mamĕlĕk֣wòţ ha⁠ġwòyi֑m wĕ⁠hápakĕţi֤̇y merĕká̇báh֙ wĕ⁠rò֣kĕbe֔y⁠há wĕ⁠yárĕd֤ẇ sẇsiym֙ wĕ⁠rò֣kĕbéy⁠he֔m ʼi֖yş̌ bĕ̇⁠ẖe֥reb ʼáẖiֽy⁠w׃"],[2,23,"בַּ⁠יּ֣וֹם הַ⁠ה֣וּא נְאֻם־יְהוָ֣ה צְבָא֡וֹת אֶ֠קָּחֲ⁠ךָ זְרֻבָּבֶ֨ל בֶּן־שְׁאַלְתִּיאֵ֤ל עַבְדִּ⁠י֙ נְאֻם־יְהוָ֔ה וְ⁠שַׂמְתִּ֖י⁠ךָ כַּֽ⁠חוֹתָ֑ם כִּֽי־בְ⁠ךָ֣ בָחַ֔רְתִּי נְאֻ֖ם יְהוָ֥ה צְבָאֽוֹת׃","bȧ⁠ẏ֣wòm ha⁠h֣ẇʼ nĕʼum-yĕhwá֣h ẕĕbáʼ֡wòţ ʼe֠qá̇ẖà⁠ká zĕrubá̇be֨l bėn-şĕ̌ʼalĕţi̇yʼé֤l ʻabĕdi̇⁠y֙ nĕʼum-yĕhwá֔h wĕ⁠şâmĕţi֖̇y⁠ká kȧֽ⁠ẖwòţá֑m kiֽ̇y-bĕ⁠ká֣ báẖa֔rĕţi̇y nĕʼu֖m yĕhwá֥h ẕĕbáʼֽwòţ׃"]],"fra-lsg1910":[[1,1,"La seconde année du roi Darius, le premier jour du sixième mois, la parole de l'Éternel fut adressée par Aggée, le prophète, à Zorobabel, fils de Schealthiel, gouverneur de Juda, et à Josué, fils de Jotsadak, le souverain sacrificateur, en ces mots:","La seconde année du roi Darius, le premier jour du sixième mois, la parole de l'Éternel fut adressée par Aggée, le prophète, à Zorobabel, fils de Schealthiel, gouverneur de Juda, et à Josué, fils de Jotsadak, le souverain sacrificateur, en ces mots:"],[1,2,"Ainsi parle l'Éternel des armées: Ce peuple dit: Le temps n'est pas venu, le temps de rebâtir la maison de l'Éternel.","Ainsi parle l'Éternel des armées: Ce peuple dit: Le temps n'est pas venu, le temps de rebâtir la maison de l'Éternel."],[1,3,"C'est pourquoi la parole de l'Éternel leur fut adressée par Aggée, le prophète, en ces mots:","C'est pourquoi la parole de l'Éternel leur fut adressée par Aggée, le prophète, en ces mots:"],[1,4,"Est-ce le temps pour vous d'habiter vos demeures lambrissées, Quand cette maison est détruite?","Est-ce le temps pour vous d'habiter vos demeures lambrissées, Quand cette maison est détruite?"],[1,5,"Ainsi parle maintenant l'Éternel des armées: Considérez attentivement vos voies!","Ainsi parle maintenant l'Éternel des armées: Considérez attentivement vos voies!"],[1,6,"Vous semez beaucoup, et vous recueillez peu, Vous mangez, et vous n'êtes pas rassasiés, Vous buvez, et vous n'êtes pas désaltérés, Vous êtes vêtus, et vous n'avez pas chaud; Le salaire de celui qui est à gages tombe dans un sac percé.","Vous semez beaucoup, et vous recueillez peu, Vous mangez, et vous n'êtes pas rassasiés, Vous buvez, et vous n'êtes pas désaltérés, Vous êtes vêtus, et vous n'avez pas chaud; Le salaire de celui qui est à gages tombe dans un sac percé."],[1,7,"Ainsi parle l'Éternel des armées: Considérez attentivement vos voies!","Ainsi parle l'Éternel des armées: Considérez attentivement vos voies!"],[1,8,"Montez sur la montagne, apportez du bois, Et bâtissez la maison: J'en aurai de la joie, et je serai glorifié, Dit l'Éternel.","Montez sur la montagne, apportez du bois, Et bâtissez la maison: J'en aurai de la joie, et je serai glorifié, Dit l'Éternel."],[1,9,"Vous comptiez sur beaucoup, et voici, vous avez eu peu; Vous l'avez rentré chez vous, mais j'ai soufflé dessus. Pourquoi? dit l'Éternel des armées. À cause de ma maison, qui est détruite, Tandis que vous vous empressez chacun pour sa maison.","Vous comptiez sur beaucoup, et voici, vous avez eu peu; Vous l'avez rentré chez vous, mais j'ai soufflé dessus. Pourquoi? dit l'Éternel des armées. À cause de ma maison, qui est détruite, Tandis que vous vous empressez chacun pour sa maison."],[1,10,"C'est pourquoi les cieux vous ont refusé la rosée, Et la terre a refusé ses produits.","C'est pourquoi les cieux vous ont refusé la rosée, Et la terre a refusé ses produits."],[1,11,"J'ai appelé la sécheresse sur le pays, sur les montagnes, Sur le blé, sur le moût, sur l'huile, Sur ce que la terre peut rapporter, Sur les hommes et sur les bêtes, Et sur tout le travail des mains.","J'ai appelé la sécheresse sur le pays, sur les montagnes, Sur le blé, sur le moût, sur l'huile, Sur ce que la terre peut rapporter, Sur les hommes et sur les bêtes, Et sur tout le travail des mains."],[1,12,"Zorobabel, fils de Schealthiel, Josué, fils de Jotsadak, le souverain sacrificateur, et tout le reste du peuple, entendirent la voix de l'Éternel, leur Dieu, et les paroles d'Aggée, le prophète, selon la mission que lui avait donnée l'Éternel, leur Dieu. Et le peuple fut saisi de crainte devant l'Éternel.","Zorobabel, fils de Schealthiel, Josué, fils de Jotsadak, le souverain sacrificateur, et tout le reste du peuple, entendirent la voix de l'Éternel, leur Dieu, et les paroles d'Aggée, le prophète, selon la mission que lui avait donnée l'Éternel, leur Dieu. Et le peuple fut saisi de crainte devant l'Éternel."],[1,13,"Aggée, envoyé de l'Éternel, dit au peuple, d'après l'ordre de l'Éternel: Je suis avec vous, dit l'Éternel.","Aggée, envoyé de l'Éternel, dit au peuple, d'après l'ordre de l'Éternel: Je suis avec vous, dit l'Éternel."],[1,14,"L'Éternel réveilla l'esprit de Zorobabel, fils de Schealthiel, gouverneur de Juda, et l'esprit de Josué, fils de Jotsadak, le souverain sacrificateur, et l'esprit de tout le reste du peuple. Ils vinrent, et ils se mirent à l'oeuvre dans la maison de l'Éternel des armées, leur Dieu,","L'Éternel réveilla l'esprit de Zorobabel, fils de Schealthiel, gouverneur de Juda, et l'esprit de Josué, fils de Jotsadak, le souverain sacrificateur, et l'esprit de tout le reste du peuple. Ils vinrent, et ils se mirent à l'oeuvre dans la maison de l'Éternel des armées, leur Dieu,"],[1,15,"le vingt-quatrième jour du sixième mois, la seconde année du roi Darius.","le vingt-quatrième jour du sixième mois, la seconde année du roi Darius."],[2,1,"Le vingt et unième jour du septième mois, la parole de l'Éternel se révéla par Aggée, le prophète, en ces mots:","Le vingt et unième jour du septième mois, la parole de l'Éternel se révéla par Aggée, le prophète, en ces mots:"],[2,2,"Parle à Zorobabel, fils de Schealthiel, gouverneur de Juda, à Josué, fils de Jotsadak, le souverain sacrificateur, et au reste du peuple, et dis-leur:","Parle à Zorobabel, fils de Schealthiel, gouverneur de Juda, à Josué, fils de Jotsadak, le souverain sacrificateur, et au reste du peuple, et dis-leur:"],[2,3,"Quel est parmi vous le survivant Qui ait vu cette maison dans sa gloire première? Et comment la voyez-vous maintenant? Telle qu'elle est, ne paraît-elle pas comme rien à vos yeux?","Quel est parmi vous le survivant Qui ait vu cette maison dans sa gloire première? Et comment la voyez-vous maintenant? Telle qu'elle est, ne paraît-elle pas comme rien à vos yeux?"],[2,4,"Maintenant fortifie-toi, Zorobabel! dit l'Éternel. Fortifie-toi, Josué, fils de Jotsadak, souverain sacrificateur! Fortifie-toi, peuple entier du pays! dit l'Éternel. Et travaillez! Car je suis avec vous, Dit l'Éternel des armées.","Maintenant fortifie-toi, Zorobabel! dit l'Éternel. Fortifie-toi, Josué, fils de Jotsadak, souverain sacrificateur! Fortifie-toi, peuple entier du pays! dit l'Éternel. Et travaillez! Car je suis avec vous, Dit l'Éternel des armées."],[2,5,"Je reste fidèle à l'alliance que j'ai faite avec vous Quand vous sortîtes de l'Égypte, Et mon esprit est au milieu de vous; Ne craignez pas!","Je reste fidèle à l'alliance que j'ai faite avec vous Quand vous sortîtes de l'Égypte, Et mon esprit est au milieu de vous; Ne craignez pas!"],[2,6,"Car ainsi parle l'Éternel des armées: Encore un peu de temps, Et j'ébranlerai les cieux et la terre, La mer et le sec;","Car ainsi parle l'Éternel des armées: Encore un peu de temps, Et j'ébranlerai les cieux et la terre, La mer et le sec;"],[2,7,"J'ébranlerai toutes les nations; Les trésors de toutes les nations viendront, Et je remplirai de gloire cette maison, Dit l'Éternel des armées.","J'ébranlerai toutes les nations; Les trésors de toutes les nations viendront, Et je remplirai de gloire cette maison, Dit l'Éternel des armées."],[2,8,"L'argent est à moi, et l'or est à moi, Dit l'Éternel des armées.","L'argent est à moi, et l'or est à moi, Dit l'Éternel des armées."],[2,9,"La gloire de cette dernière maison sera plus grande Que celle de la première, Dit l'Éternel des armées; Et c'est dans ce lieu que je donnerai la paix, Dit l'Éternel des armées.","La gloire de cette dernière maison sera plus grande Que celle de la première, Dit l'Éternel des armées; Et c'est dans ce lieu que je donnerai la paix, Dit l'Éternel des armées."],[2,10,"le vingt-quatrième jour du neuvième mois, la seconde année de Darius, la parole de l'Éternel se révéla par Aggée, le prophète, en ces mots:","le vingt-quatrième jour du neuvième mois, la seconde année de Darius, la parole de l'Éternel se révéla par Aggée, le prophète, en ces mots:"],[2,11,"Ainsi parle l'Éternel des armées: Propose aux sacrificateurs cette question sur la loi:","Ainsi parle l'Éternel des armées: Propose aux sacrificateurs cette question sur la loi:"],[2,12,"Si quelqu'un porte dans le pan de son vêtement de la chair consacrée, et qu'il touche avec son vêtement du pain, des mets, du vin, de l'huile, ou un aliment quelconque, ces choses seront-elles sanctifiées? Les sacrificateurs répondirent: Non!","Si quelqu'un porte dans le pan de son vêtement de la chair consacrée, et qu'il touche avec son vêtement du pain, des mets, du vin, de l'huile, ou un aliment quelconque, ces choses seront-elles sanctifiées? Les sacrificateurs répondirent: Non!"],[2,13,"Et Aggée dit: Si quelqu'un souillé par le contact d'un cadavre touche toutes ces choses, seront-elles souillées? Les sacrificateurs répondirent: Elles seront souillées.","Et Aggée dit: Si quelqu'un souillé par le contact d'un cadavre touche toutes ces choses, seront-elles souillées? Les sacrificateurs répondirent: Elles seront souillées."],[2,14,"Alors Aggée, reprenant la parole, dit: Tel est ce peuple, telle est cette nation devant moi, dit l'Éternel, Telles sont toutes les oeuvres de leurs mains; Ce qu'ils m'offrent là est souillé.","Alors Aggée, reprenant la parole, dit: Tel est ce peuple, telle est cette nation devant moi, dit l'Éternel, Telles sont toutes les oeuvres de leurs mains; Ce qu'ils m'offrent là est souillé."],[2,15,"Considérez donc attentivement Ce qui s'est passé jusqu'à ce jour, Avant qu'on eût mis pierre sur pierre au temple de l'Éternel!","Considérez donc attentivement Ce qui s'est passé jusqu'à ce jour, Avant qu'on eût mis pierre sur pierre au temple de l'Éternel!"],[2,16,"Alors, quand on venait à un tas de vingt mesures, Il n'y en avait que dix; Quand on venait à la cuve pour puiser cinquante mesures, Il n'y en avait que vingt.","Alors, quand on venait à un tas de vingt mesures, Il n'y en avait que dix; Quand on venait à la cuve pour puiser cinquante mesures, Il n'y en avait que vingt."],[2,17,"Je vous ai frappés par la rouille et par la nielle, et par la grêle; J'ai frappé tout le travail de vos mains. Malgré cela, vous n'êtes pas revenus à moi, dit l'Éternel.","Je vous ai frappés par la rouille et par la nielle, et par la grêle; J'ai frappé tout le travail de vos mains. Malgré cela, vous n'êtes pas revenus à moi, dit l'Éternel."],[2,18,"Considérez attentivement Ce qui s'est passé jusqu'à ce jour, Jusqu'au vingt-quatrième jour du neuvième mois, Depuis le jour où le temple de l'Éternel a été fondé, Considérez-le attentivement!","Considérez attentivement Ce qui s'est passé jusqu'à ce jour, Jusqu'au vingt-quatrième jour du neuvième mois, Depuis le jour où le temple de l'Éternel a été fondé, Considérez-le attentivement!"],[2,19,"Y avait-il encore de la semence dans les greniers? Même la vigne, le figuier, le grenadier et l'olivier, N'ont rien rapporté. Mais dès ce jour je répandrai ma bénédiction.","Y avait-il encore de la semence dans les greniers? Même la vigne, le figuier, le grenadier et l'olivier, N'ont rien rapporté. Mais dès ce jour je répandrai ma bénédiction."],[2,20,"La parole de l'Éternel fut adressée pour la seconde fois à Aggée, le vingt-quatrième jour du mois, en ces mots:","La parole de l'Éternel fut adressée pour la seconde fois à Aggée, le vingt-quatrième jour du mois, en ces mots:"],[2,21,"Parle à Zorobabel, gouverneur de Juda, et dis: J'ébranlerai les cieux et la terre;","Parle à Zorobabel, gouverneur de Juda, et dis: J'ébranlerai les cieux et la terre;"],[2,22,"Je renverserai le trône des royaumes, Je détruirai la force des royaumes des nations, Je renverserai les chars et ceux qui les montent; Les chevaux et leurs cavaliers seront abattus, L'un par l'épée de l'autre.","Je renverserai le trône des royaumes, Je détruirai la force des royaumes des nations, Je renverserai les chars et ceux qui les montent; Les chevaux et leurs cavaliers seront abattus, L'un par l'épée de l'autre."],[2,23,"En ce jour-là, dit l'Éternel des armées, Je te prendrai, Zorobabel, fils de Schealthiel, Mon serviteur, dit l'Éternel, Et je te garderai comme un sceau; Car je t'ai choisi, dit l'Éternel des armées.","En ce jour-là, dit l'Éternel des armées, Je te prendrai, Zorobabel, fils de Schealthiel, Mon serviteur, dit l'Éternel, Et je te garderai comme un sceau; Car je t'ai choisi, dit l'Éternel des armées."]],"spa-rv1909":[[1,1,"EN el añosegundodel reyDaríoen el messexto, en el primerdíadel mes, fuépalabrade Jehová, por manodel profetaHaggeo, á Zorobabelhijode Sealtiel, gobernadorde Judá, y áJosuéhijode Josadac, gransacerdote, diciendo:","EN el añosegundodel reyDaríoen el messexto, en el primerdíadel mes, fuépalabrade Jehová, por manodel profetaHaggeo, á Zorobabelhijode Sealtiel, gobernadorde Judá, y áJosuéhijode Josadac, gransacerdote, diciendo:"],[1,2,"Jehováde los ejércitoshabla así, diciendo: Este pueblodice: Noes aún venidoel tiempo, el tiempode que la casade Jehovásea reedificada.","Jehováde los ejércitoshabla así, diciendo: Este pueblodice: Noes aún venidoel tiempo, el tiempode que la casade Jehovásea reedificada."],[1,3,"Fuépues palabrade Jehovápor manodel profetaHaggeo, diciendo:","Fuépues palabrade Jehovápor manodel profetaHaggeo, diciendo:"],[1,4,"¿Es para vosotrostiempo, para vosotros, de moraren vuestrascasasenmaderadas, y esta casa está desierta?","¿Es para vosotrostiempo, para vosotros, de moraren vuestrascasasenmaderadas, y esta casa está desierta?"],[1,5,"Pues asíha dichoJehováde los ejércitos: Pensadbien sobrevuestros caminos.","Pues asíha dichoJehováde los ejércitos: Pensadbien sobrevuestros caminos."],[1,6,"Sembráismucho, y encerráis poco; coméis, y noos hartáis; bebéis, y noos saciáis; os vestís, y noos calentáis; y el que anda á jornalrecibe su jornalentrapo horadado.","Sembráismucho, y encerráis poco; coméis, y noos hartáis; bebéis, y noos saciáis; os vestís, y noos calentáis; y el que anda á jornalrecibe su jornalentrapo horadado."],[1,7,"Asíha dichoJehováde los ejércitos: Meditadsobrevuestros caminos.","Asíha dichoJehováde los ejércitos: Meditadsobrevuestros caminos."],[1,8,"Subidal monte, y traedmadera, y reedificadla casa; y pondré en ella mi voluntad, y seré honrado, ha dichoJehová.","Subidal monte, y traedmadera, y reedificadla casa; y pondré en ella mi voluntad, y seré honrado, ha dichoJehová."],[1,9,"Buscáismucho, y halláis poco; y encerráisen casa, y soploen ello. ¿Por qué? diceJehováde los ejércitos. Por cuantomi casaestá desierta, y cada unode vosotros correá supropia casa.","Buscáismucho, y halláis poco; y encerráisen casa, y soploen ello. ¿Por qué? diceJehováde los ejércitos. Por cuantomi casaestá desierta, y cada unode vosotros correá supropia casa."],[1,10,"Poresose detuvode los cielossobrevosotros la lluvia, y la tierradetuvosus frutos.","Poresose detuvode los cielossobrevosotros la lluvia, y la tierradetuvosus frutos."],[1,11,"Y llaméla sequedadsobreesta tierra, y sobrelos montes, y sobreel trigo, y sobreel vino, y sobreel aceite, y sobretodo lo quela tierraproduce, y sobrelos hombresy sobrelas bestias, y sobretodotrabajode manos.","Y llaméla sequedadsobreesta tierra, y sobrelos montes, y sobreel trigo, y sobreel vino, y sobreel aceite, y sobretodo lo quela tierraproduce, y sobrelos hombresy sobrelas bestias, y sobretodotrabajode manos."],[1,12,"Y oyóZorobabelhijode Sealtiel, y Josuéhijode Josadac, gransacerdote, y todoel demás pueblo, la vozde Jehovásu Dios, y las palabrasdel profetaHaggeo, como lo había enviadoJehováel Diosde ellos; y temióel pueblodelantede Jehová.","Y oyóZorobabelhijode Sealtiel, y Josuéhijode Josadac, gransacerdote, y todoel demás pueblo, la vozde Jehovásu Dios, y las palabrasdel profetaHaggeo, como lo había enviadoJehováel Diosde ellos; y temióel pueblodelantede Jehová."],[1,13,"Entonces Haggeo, enviadode Jehová, hablópor mandado de Jehová, al pueblo, diciendo: Yosoy convosotros, diceJehová.","Entonces Haggeo, enviadode Jehová, hablópor mandado de Jehová, al pueblo, diciendo: Yosoy convosotros, diceJehová."],[1,14,"Y despertóJehováel espíritude Zorobabelhijode Sealtiel, gobernadorde Judá, y el espíritude Josuéhijode Josadac, gransacerdote, y el espíritude todoel restodel pueblo; y vinieroné hicieronobra en la casade Jehováde los ejércitos, su Dios,","Y despertóJehováel espíritude Zorobabelhijode Sealtiel, gobernadorde Judá, y el espíritude Josuéhijode Josadac, gransacerdote, y el espíritude todoel restodel pueblo; y vinieroné hicieronobra en la casade Jehováde los ejércitos, su Dios,"],[1,15,"En el díaveintey cuatrodel messexto, en el segundoañodel reyDarío.","En el díaveintey cuatrodel messexto, en el segundoañodel reyDarío."],[2,1,"EN el messéptimo, á los veintey unodel mes, fuépalabrade Jehovápor manodel profetaHaggeo, diciendo:","EN el messéptimo, á los veintey unodel mes, fuépalabrade Jehovápor manodel profetaHaggeo, diciendo:"],[2,2,"Hablaahoraá Zorobabelhijode Sealtiel, gobernadorde Judá, y áJosuéhijode Josadac, gransacerdote, y alrestodel pueblo, diciendo:","Hablaahoraá Zorobabelhijode Sealtiel, gobernadorde Judá, y áJosuéhijode Josadac, gransacerdote, y alrestodel pueblo, diciendo:"],[2,3,"¿Quiénha quedadoentre vosotrosquehaya vistoesta casaen su primeragloria, y cual ahorala veis? ¿Noes ella como nadadelante de vuestrosojos?","¿Quiénha quedadoentre vosotrosquehaya vistoesta casaen su primeragloria, y cual ahorala veis? ¿Noes ella como nadadelante de vuestrosojos?"],[2,4,"Pues ahora, Zorobabel, esfuérzate, diceJehová; esfuérzatetambién Josué, hijode Josadac, gransacerdote; y cobra ánimo, pueblotodode la tierra, diceJehová, y obrad: porqueyosoy convosotros, diceJehováde los ejércitos.","Pues ahora, Zorobabel, esfuérzate, diceJehová; esfuérzatetambién Josué, hijode Josadac, gransacerdote; y cobra ánimo, pueblotodode la tierra, diceJehová, y obrad: porqueyosoy convosotros, diceJehováde los ejércitos."],[2,5,"Segúnel pactoqueconcerté con vosotrosá vuestra salida de Egipto, así mi espírituestaráen mediode vosotros: notemáis.","Segúnel pactoqueconcerté con vosotrosá vuestra salida de Egipto, así mi espírituestaráen mediode vosotros: notemáis."],[2,6,"PorqueasídiceJehováde los ejércitos: Deaquíá pocoaun haré yotemblarlos cielosy la tierra, y la mary la seca:","PorqueasídiceJehováde los ejércitos: Deaquíá pocoaun haré yotemblarlos cielosy la tierra, y la mary la seca:"],[2,7,"Y haré temblará todaslas gentes, y vendráel Deseadode todaslas gentes; y henchiréesta casade gloria, ha dichoJehováde los ejércitos.","Y haré temblará todaslas gentes, y vendráel Deseadode todaslas gentes; y henchiréesta casade gloria, ha dichoJehováde los ejércitos."],[2,8,"Mía es la plata, y mío el oro, diceJehováde los ejércitos.","Mía es la plata, y mío el oro, diceJehováde los ejércitos."],[2,9,"La gloria de aquesta casapostreraserámayorquela de la primera, ha dichoJehováde los ejércitos; y darépazen este lugar, diceJehováde los ejércitos.","La gloria de aquesta casapostreraserámayorquela de la primera, ha dichoJehováde los ejércitos; y darépazen este lugar, diceJehováde los ejércitos."],[2,10,"A veinticuatrodel novenomes, en el segundoañode Darío, fuépalabrade Jehovápormano del profetaHaggeo, diciendo:","A veinticuatrodel novenomes, en el segundoañode Darío, fuépalabrade Jehovápormano del profetaHaggeo, diciendo:"],[2,11,"Asíha dichoJehováde los ejércitos: Preguntaahoraá los sacerdotesacerca de la ley, diciendo:","Asíha dichoJehováde los ejércitos: Preguntaahoraá los sacerdotesacerca de la ley, diciendo:"],[2,12,"Sillevarealgunolas carnes sagradas en la faldade su ropa, y con el vuelode ellatocareel pan, ó la vianda, ó el vino, ó el aceite, ú otra cualquiercomida, ¿será santificado? Y respondieronlos sacerdotes, y dijeron: No.","Sillevarealgunolas carnes sagradas en la faldade su ropa, y con el vuelode ellatocareel pan, ó la vianda, ó el vino, ó el aceite, ú otra cualquiercomida, ¿será santificado? Y respondieronlos sacerdotes, y dijeron: No."],[2,13,"Y dijoHaggeo: Siun inmundoá causa de cuerpo muertotocare alguna cosade éstas, ¿será inmunda? Y respondieronlos sacerdotes, y dijeron: Inmundaserá.","Y dijoHaggeo: Siun inmundoá causa de cuerpo muertotocare alguna cosade éstas, ¿será inmunda? Y respondieronlos sacerdotes, y dijeron: Inmundaserá."],[2,14,"Y respondióHaggeoy dijo: Asíes este pueblo, y esta gente, delantede mí, diceJehová; y asimismotodaobrade sus manos; y todo lo queaquíofrecenes inmundo.","Y respondióHaggeoy dijo: Asíes este pueblo, y esta gente, delantede mí, diceJehová; y asimismotodaobrade sus manos; y todo lo queaquíofrecenes inmundo."],[2,15,"Ahorapues, ponedvuestro corazóndesdeeste díaen adelante, antesque pusiesen piedrasobrepiedraen el templode Jehová,","Ahorapues, ponedvuestro corazóndesdeeste díaen adelante, antesque pusiesen piedrasobrepiedraen el templode Jehová,"],[2,16,"Antes que fuesen estas cosas, veníanalmontónde veintehanegas, y habíadiez; veníanallagarpara sacarcincuentacántarosdel lagar, y habíaveinte.","Antes que fuesen estas cosas, veníanalmontónde veintehanegas, y habíadiez; veníanallagarpara sacarcincuentacántarosdel lagar, y habíaveinte."],[2,17,"Os herícon vientosolano, y con tizoncillo, y con granizoen todaobrade vuestras manos; mas noos convertisteisámí, diceJehová.","Os herícon vientosolano, y con tizoncillo, y con granizoen todaobrade vuestras manos; mas noos convertisteisámí, diceJehová."],[2,18,"Puesponedahora vuestro corazóndesdeeste díaen adelante, desdeel díaveinticuatrodel novenomes, desdeel díaquese echó el cimientoal templode Jehová; poned vuestro corazón.","Puesponedahora vuestro corazóndesdeeste díaen adelante, desdeel díaveinticuatrodel novenomes, desdeel díaquese echó el cimientoal templode Jehová; poned vuestro corazón."],[2,19,"¿Aunno está la simienteen el granero? Ni la vid, ni la higuera, ni el granado, ni el árbolde la olivaha todavíaflorecido: mas desdeaqueste díadaré bendición.","¿Aunno está la simienteen el granero? Ni la vid, ni la higuera, ni el granado, ni el árbolde la olivaha todavíaflorecido: mas desdeaqueste díadaré bendición."],[2,20,"Y fuésegundavez palabrade Jehováá Haggeo, á los veinticuatrodel mismo mes, diciendo:","Y fuésegundavez palabrade Jehováá Haggeo, á los veinticuatrodel mismo mes, diciendo:"],[2,21,"HablaáZorobabel, gobernadorde Judá, diciendo: Yoharé temblarlos cielosy la tierra;","HablaáZorobabel, gobernadorde Judá, diciendo: Yoharé temblarlos cielosy la tierra;"],[2,22,"Y trastornaréel tronode los reinos, y destruiréla fuerzadel reinode las gentes; y trastornaréel carro, y los que en él suben; y vendrán abajolos caballos, y los que en ellos montan, cada cualpor la espadade su hermano.","Y trastornaréel tronode los reinos, y destruiréla fuerzadel reinode las gentes; y trastornaréel carro, y los que en él suben; y vendrán abajolos caballos, y los que en ellos montan, cada cualpor la espadade su hermano."],[2,23,"En aquel día, diceJehováde los ejércitos, te tomaré, oh Zorobabel, hijode Sealtiel, siervomío, diceJehová, y ponertehe como anillo de sellar: porqueyo te escogí, diceJehováde los ejércitos.","En aquel día, diceJehováde los ejércitos, te tomaré, oh Zorobabel, hijode Sealtiel, siervomío, diceJehová, y ponertehe como anillo de sellar: porqueyo te escogí, diceJehováde los ejércitos."]],"rus-synodal":[[1,1,"Во второй год царя Дария, в шестой месяц, в первый день месяца, было слово Господне через Аггея пророка к Зоровавелю, сыну Салафиилеву, правителю Иудеи, и к Иисусу, сыну Иоседекову, великому иерею:","Vo vtoroj god carâ Dariâ, v šestoj mesâc, v pervyj denʹ mesâca, bylo slovo Gospodne čerez Aggeâ proroka k Zorovavelû, synu Salafiilevu, pravitelû Iudei, i k Iisusu, synu Iosedekovu, velikomu iereû:"],[1,2,"Так сказал Господь Саваоф: народ сей говорит: «не пришло еще время, не время строить дом Господень».","Tak skazal Gospodʹ Savaof: narod sej govorit: «ne prišlo eŝe vremâ, ne vremâ stroitʹ dom Gospodenʹ»."],[1,3,"И было слово Господне через Аггея пророка:","I bylo slovo Gospodne čerez Aggeâ proroka:"],[1,4,"а вам самим время жить в домах ваших украшенных, тогда как дом сей в запустении?","a vam samim vremâ žitʹ v domah vaših ukrašennyh, togda kak dom sej v zapustenii?"],[1,5,"Посему ныне так говорит Господь Саваоф: обратите сердце ваше на пути ваши.","Posemu nyne tak govorit Gospodʹ Savaof: obratite serdce vaše na puti vaši."],[1,6,"Вы сеете много, а собираете мало; едите, но не в сытость; пьете, но не напиваетесь; одеваетесь, а не согреваетесь; зарабатывающий плату зарабатывает для дырявого кошелька.","Vy seete mnogo, a sobiraete malo; edite, no ne v sytostʹ; pʹete, no ne napivaetesʹ; odevaetesʹ, a ne sogrevaetesʹ; zarabatyvaûŝij platu zarabatyvaet dlâ dyrâvogo košelʹka."],[1,7,"Так говорит Господь Саваоф: обратите сердце ваше на пути ваши.","Tak govorit Gospodʹ Savaof: obratite serdce vaše na puti vaši."],[1,8,"Взойдите на гору и носите дерева, и стройте храм; и Я буду благоволить к нему и прославлюсь, говорит Господь.","Vzojdite na goru i nosite dereva, i strojte hram; i Â budu blagovolitʹ k nemu i proslavlûsʹ, govorit Gospodʹ."],[1,9,"Ожидаете многого, а выходит мало; и что принесете домой, то Я развею. – За что? говорит Господь Саваоф: за Мой дом, который в запустении, тогда как вы бежите каждый к своему дому.","Ožidaete mnogogo, a vyhodit malo; i čto prinesete domoj, to Â razveû. – Za čto? govorit Gospodʹ Savaof: za Moj dom, kotoryj v zapustenii, togda kak vy bežite každyj k svoemu domu."],[1,10,"Посему-то небо заключилось и не дает вам росы, и земля не дает своих произведений.","Posemu-to nebo zaklûčilosʹ i ne daet vam rosy, i zemlâ ne daet svoih proizvedenij."],[1,11,"И Я призвал засуху на землю, на горы, на хлеб, на виноградный сок, на елей и на все, что производит земля, и на человека, и на скот, и на всякий ручной труд.","I Â prizval zasuhu na zemlû, na gory, na hleb, na vinogradnyj sok, na elej i na vse, čto proizvodit zemlâ, i na čeloveka, i na skot, i na vsâkij ručnoj trud."],[1,12,"И послушались Зоровавель, сын Салафиилев, и Иисус, сын Иоседеков, и весь прочий народ гласа Господа Бога своего и слов Аггея пророка, как посланного Господом Богом их, и народ убоялся Господа.","I poslušalisʹ Zorovavelʹ, syn Salafiilev, i Iisus, syn Iosedekov, i vesʹ pročij narod glasa Gospoda Boga svoego i slov Aggeâ proroka, kak poslannogo Gospodom Bogom ih, i narod uboâlsâ Gospoda."],[1,13,"Тогда Аггей, вестник Господень, посланный от Господа, сказал к народу: Я с вами! говорит Господь.","Togda Aggej, vestnik Gospodenʹ, poslannyj ot Gospoda, skazal k narodu: Â s vami! govorit Gospodʹ."],[1,14,"И возбудил Господь дух Зоровавеля, сына Салафиилева, правителя Иудеи, и дух Иисуса, сына Иоседекова, великого иерея, и дух всего остатка народа, и они пришли и стали производить работы в доме Господа Саваофа, Бога своего,","I vozbudil Gospodʹ duh Zorovavelâ, syna Salafiileva, pravitelâ Iudei, i duh Iisusa, syna Iosedekova, velikogo iereâ, i duh vsego ostatka naroda, i oni prišli i stali proizvoditʹ raboty v dome Gospoda Savaofa, Boga svoego,"],[1,15,"в двадцать четвертый день шестого месяца, во второй год царя Дария.","v dvadcatʹ četvertyj denʹ šestogo mesâca, vo vtoroj god carâ Dariâ."],[2,1,"В седьмой месяц, в двадцать первый день месяца, было слово Господне через Аггея пророка:","V sedʹmoj mesâc, v dvadcatʹ pervyj denʹ mesâca, bylo slovo Gospodne čerez Aggeâ proroka:"],[2,2,"скажи теперь Зоровавелю, сыну Салафиилеву, правителю Иудеи, и Иисусу, сыну Иоседекову, великому иерею, и остатку народа:","skaži teperʹ Zorovavelû, synu Salafiilevu, pravitelû Iudei, i Iisusu, synu Iosedekovu, velikomu iereû, i ostatku naroda:"],[2,3,"кто остался между вами, который видел этот дом в прежней его славе, и каким видите вы его теперь? Не есть ли он в глазах ваших как бы ничто?","kto ostalsâ meždu vami, kotoryj videl étot dom v prežnej ego slave, i kakim vidite vy ego teperʹ? Ne estʹ li on v glazah vaših kak by ničto?"],[2,4,"Но ободрись ныне, Зоровавель, говорит Господь, ободрись, Иисус, сын Иоседеков, великий иерей! ободрись, весь народ земли, говорит Господь, и производите работы, ибо Я с вами, говорит Господь Саваоф.","No obodrisʹ nyne, Zorovavelʹ, govorit Gospodʹ, obodrisʹ, Iisus, syn Iosedekov, velikij ierej! obodrisʹ, vesʹ narod zemli, govorit Gospodʹ, i proizvodite raboty, ibo Â s vami, govorit Gospodʹ Savaof."],[2,5,"Завет Мой, который Я заключил с вами при исшествии вашем из Египта, и дух Мой пребывает среди вас: не бойтесь!","Zavet Moj, kotoryj Â zaklûčil s vami pri isšestvii vašem iz Egipta, i duh Moj prebyvaet sredi vas: ne bojtesʹ!"],[2,6,"Ибо так говорит Господь Саваоф: еще раз, и это будет скоро, Я потрясу небо и землю, море и сушу,","Ibo tak govorit Gospodʹ Savaof: eŝe raz, i éto budet skoro, Â potrâsu nebo i zemlû, more i sušu,"],[2,7,"и потрясу все народы, и придет Желаемый всеми народами, и наполню дом сей славою, говорит Господь Саваоф.","i potrâsu vse narody, i pridet Želaemyj vsemi narodami, i napolnû dom sej slavoû, govorit Gospodʹ Savaof."],[2,8,"Мое серебро и Мое золото, говорит Господь Саваоф.","Moe serebro i Moe zoloto, govorit Gospodʹ Savaof."],[2,9,"Слава сего последнего храма будет больше, нежели прежнего, говорит Господь Саваоф; и на месте сем Я дам мир, говорит Господь Саваоф.","Slava sego poslednego hrama budet bolʹše, neželi prežnego, govorit Gospodʹ Savaof; i na meste sem Â dam mir, govorit Gospodʹ Savaof."],[2,10,"В двадцать четвертый день девятого месяца, во второй год Дария, было слово Господне через Аггея пророка:","V dvadcatʹ četvertyj denʹ devâtogo mesâca, vo vtoroj god Dariâ, bylo slovo Gospodne čerez Aggeâ proroka:"],[2,11,"так говорит Господь Саваоф: спроси священников о законе и скажи:","tak govorit Gospodʹ Savaof: sprosi svâŝennikov o zakone i skaži:"],[2,12,"если бы кто нес освященное мясо в поле одежды своей и полою своею коснулся хлеба, или чего-либо вареного, или вина, или елея, или какой-нибудь пищи: сделается ли это священным? И отвечали священники и сказали: нет.","esli by kto nes osvâŝennoe mâso v pole odeždy svoej i poloû svoeû kosnulsâ hleba, ili čego-libo varenogo, ili vina, ili eleâ, ili kakoj-nibudʹ piŝi: sdelaetsâ li éto svâŝennym? I otvečali svâŝenniki i skazali: net."],[2,13,"Потом сказал Аггей: а если прикоснется ко всему этому кто-либо, осквернившийся от прикосновения к мертвецу: сделается ли это нечистым? И отвечали священники и сказали: будет нечистым.","Potom skazal Aggej: a esli prikosnetsâ ko vsemu étomu kto-libo, oskvernivšijsâ ot prikosnoveniâ k mertvecu: sdelaetsâ li éto nečistym? I otvečali svâŝenniki i skazali: budet nečistym."],[2,14,"Тогда отвечал Аггей и сказал: таков этот народ, таково это племя предо Мною, говорит Господь, и таковы все дела рук их! И что они приносят там, все нечисто.","Togda otvečal Aggej i skazal: takov étot narod, takovo éto plemâ predo Mnoû, govorit Gospodʹ, i takovy vse dela ruk ih! I čto oni prinosât tam, vse nečisto."],[2,15,"Теперь обратите сердце ваше на время от сего дня и назад, когда еще не был положен камень на камень в храме Господнем.","Teperʹ obratite serdce vaše na vremâ ot sego dnâ i nazad, kogda eŝe ne byl položen kamenʹ na kamenʹ v hrame Gospodnem."],[2,16,"Приходили, бывало, к копне, могущей приносить двадцать мер, и оказывалось только десять; приходили к подточилию, чтобы начерпать пятьдесят мер из подточилия, а оказывалось только двадцать.","Prihodili, byvalo, k kopne, moguŝej prinositʹ dvadcatʹ mer, i okazyvalosʹ tolʹko desâtʹ; prihodili k podtočiliû, čtoby načerpatʹ pâtʹdesât mer iz podtočiliâ, a okazyvalosʹ tolʹko dvadcatʹ."],[2,17,"Поражал Я вас ржавчиною и блеклостью хлеба и градом все труды рук ваших; но вы не обращались ко Мне, говорит Господь.","Poražal Â vas ržavčinoû i bleklostʹû hleba i gradom vse trudy ruk vaših; no vy ne obraŝalisʹ ko Mne, govorit Gospodʹ."],[2,18,"Обратите же сердце ваше на время от сего дня и назад, от двадцать четвертого дня девятого месяца, от того дня, когда основан был храм Господень; обратите сердце ваше:","Obratite že serdce vaše na vremâ ot sego dnâ i nazad, ot dvadcatʹ četvertogo dnâ devâtogo mesâca, ot togo dnâ, kogda osnovan byl hram Gospodenʹ; obratite serdce vaše:"],[2,19,"есть ли еще в житницах семена? Доселе ни виноградная лоза, ни смоковница, ни гранатовое дерево, ни маслина не давали плода; а от сего дня Я благословлю их.","estʹ li eŝe v žitnicah semena? Dosele ni vinogradnaâ loza, ni smokovnica, ni granatovoe derevo, ni maslina ne davali ploda; a ot sego dnâ Â blagoslovlû ih."],[2,20,"И было слово Господне к Аггею вторично в двадцать четвертый день месяца, и сказано:","I bylo slovo Gospodne k Aggeû vtorično v dvadcatʹ četvertyj denʹ mesâca, i skazano:"],[2,21,"скажи Зоровавелю, правителю Иудеи: потрясу Я небо и землю;","skaži Zorovavelû, pravitelû Iudei: potrâsu Â nebo i zemlû;"],[2,22,"и ниспровергну престолы царств, и истреблю силу царств языческих, опрокину колесницы и сидящих на них, и низринуты будут кони и всадники их, один мечом другого.","i nisprovergnu prestoly carstv, i istreblû silu carstv âzyčeskih, oprokinu kolesnicy i sidâŝih na nih, i nizrinuty budut koni i vsadniki ih, odin mečom drugogo."],[2,23,"В тот день, говорит Господь Саваоф, Я возьму тебя, Зоровавель, сын Салафиилев, раб Мой, говорит Господь, и буду держать тебя как печать, ибо Я избрал тебя, говорит Господь Саваоф.","V tot denʹ, govorit Gospodʹ Savaof, Â vozʹmu tebâ, Zorovavelʹ, syn Salafiilev, rab Moj, govorit Gospodʹ, i budu deržatʹ tebâ kak pečatʹ, ibo Â izbral tebâ, govorit Gospodʹ Savaof."]],"cmn-cuv-hant":[[1,1,"大流士王第二年六月初一日，耶和華的話藉先知 哈該向 猶大省長 撒拉鐵的兒子 所羅巴伯和 約撒答的兒子大祭司 約書亞說：","dà liú shì wáng dì èr nián liù yuè chū yī rì， yé hé huá de huà jí xiān zhī hā gāi xiàng yóu dà shěng zhǎng sā lā tiě de ér zǐ suǒ luó bā bó hé yuē sā dá de ér zǐ dà jì sī yuē shū yà shuō："],[1,2,"萬軍之耶和華如此說：「這百姓說，建造耶和華殿的時候尚未來到。」","wàn jūn zhī yé hé huá rú cǐ shuō：‘zhè bǎi xìng shuō， jiàn zào yé hé huá diàn de shí hòu shàng wèi lái dào.’"],[1,3,"那時耶和華的話臨到先知 哈該說：","nà shí yé hé huá de huà lín dào xiān zhī hā gāi shuō："],[1,4,"「這殿仍然荒涼，你們自己還住天花板的房屋嗎？","‘zhè diàn réng rán huāng liáng， nǐ men zì jǐ hái zhù tiān huā bǎn de fáng wū ma？"],[1,5,"現在萬軍之耶和華如此說：你們要省察自己的行為。","xiàn zài wàn jūn zhī yé hé huá rú cǐ shuō： nǐ men yào shěng chá zì jǐ de xíng wèi."],[1,6,"你們撒的種多，收的卻少；你們吃，卻不得飽；喝，卻不得足；穿衣服，卻不得暖；得工錢的，將工錢 裝在破漏的囊中。」","nǐ men sā de zhǒng duō， shōu de què shǎo； nǐ men chī， què bù dé bǎo； hē， què bù dé zú； chuān yī fú， què bù dé nuǎn； dé gōng qián de， jiāng gōng qián zhuāng zài pò lòu de náng zhōng.’"],[1,7,"萬軍之耶和華如此說：「你們要省察自己的行為。","wàn jūn zhī yé hé huá rú cǐ shuō：‘nǐ men yào shěng chá zì jǐ de xíng wèi."],[1,8,"你們要上山取木料，建造這殿，我就因此喜樂，且得榮耀。這是耶和華說的。","nǐ men yào shàng shān qǔ mù liào， jiàn zào zhè diàn， wǒ jiù yīn cǐ xǐ lè， qiě dé róng yào. zhè shì yé hé huá shuō de."],[1,9,"你們盼望多得，所得的卻少；你們收到家中，我就吹去。這是為甚麼呢？因為我的殿荒涼，你們各人卻顧自己的房屋。這是萬軍之耶和華說的。","nǐ men pàn wàng duō dé， suǒ dé de què shǎo； nǐ men shōu dào jiā zhōng， wǒ jiù chuī qù. zhè shì wèi shèn me ne？ yīn wèi wǒ de diàn huāng liáng， nǐ men gè rén què gù zì jǐ de fáng wū. zhè shì wàn jūn zhī yé hé huá shuō de."],[1,10,"所以為你們的緣故，天就不降甘露，地也不出土產。","suǒ yǐ wèi nǐ men de yuán gù， tiān jiù bù jiàng gān lù， de yě bù chū tǔ chǎn."],[1,11,"我命乾旱臨到地土、山岡、五穀、新酒，和油，並地上的出產、人民、牲畜，以及人手一切勞碌得來的。」","wǒ mìng qián hàn lín dào de tǔ, shān gāng, wǔ gǔ, xīn jiǔ， hé yóu， bìng de shàng de chū chǎn, rén mín, shēng chù， yǐ jí rén shǒu yī qiè láo lù dé lái de.’"],[1,12,"那時， 撒拉鐵的兒子 所羅巴伯和 約撒答的兒子大祭司 約書亞，並剩下的百姓，都聽從耶和華－他們神的話和先知 哈該奉耶和華－他們神差來所說的話；百姓也在耶和華面前存敬畏的心。","nà shí， sā lā tiě de ér zǐ suǒ luó bā bó hé yuē sā dá de ér zǐ dà jì sī yuē shū yà， bìng shèng xià de bǎi xìng， dōu tīng cóng yé hé huá－tā men shén de huà hé xiān zhī hā gāi fèng yé hé huá－tā men shén chà lái suǒ shuō de huà； bǎi xìng yě zài yé hé huá miàn qián cún jìng wèi de xīn."],[1,13,"耶和華的使者 哈該奉耶和華差遣對百姓說：「耶和華說：我與你們同在。」","yé hé huá de shǐ zhě hā gāi fèng yé hé huá chà qiǎn duì bǎi xìng shuō：‘yé hé huá shuō： wǒ yǔ nǐ men tóng zài.’"],[1,14,"耶和華激動 猶大省長 撒拉鐵的兒子 所羅巴伯和 約撒答的兒子大祭司 約書亞，並剩下之百姓的心，他們就來為萬軍之耶和華－他們神的殿做工。","yé hé huá jī dòng yóu dà shěng zhǎng sā lā tiě de ér zǐ suǒ luó bā bó hé yuē sā dá de ér zǐ dà jì sī yuē shū yà， bìng shèng xià zhī bǎi xìng de xīn， tā men jiù lái wèi wàn jūn zhī yé hé huá－tā men shén de diàn zuò gōng."],[1,15,"這是在 大流士王第二年六月二十四日。","zhè shì zài dà liú shì wáng dì èr nián liù yuè èr shí sì rì."],[2,1,"七 月二十一 日，耶和華的話臨到先知 哈該說：","qī yuè èr shí yī rì， yé hé huá de huà lín dào xiān zhī hā gāi shuō："],[2,2,"「你要曉諭 猶大省長 撒拉鐵的兒子 所羅巴伯和 約撒答的兒子大祭司 約書亞，並剩下的百姓，說：","‘nǐ yào xiǎo yù yóu dà shěng zhǎng sā lā tiě de ér zǐ suǒ luó bā bó hé yuē sā dá de ér zǐ dà jì sī yuē shū yà， bìng shèng xià de bǎi xìng， shuō："],[2,3,"你們中間存留的，有誰見過這殿從前的榮耀呢？現在你們看着如何？豈不在眼中看如無有嗎？」","nǐ men zhōng jiān cún liú de， yǒu shuí jiàn guò zhè diàn cóng qián de róng yào ne？ xiàn zài nǐ men kàn zhe rú hé？ qǐ bù zài yǎn zhōng kàn rú wú yǒu ma？’"],[2,4,"耶和華說：「 所羅巴伯啊，雖然如此，你當剛強！ 約撒答的兒子大祭司 約書亞啊，你也當剛強！這地的百姓，你們都當剛強做工，因為我與你們同在。這是萬軍之耶和華說的。","yé hé huá shuō：‘ suǒ luó bā bó a， suī rán rú cǐ， nǐ dāng gāng qiáng！ yuē sā dá de ér zǐ dà jì sī yuē shū yà a， nǐ yě dāng gāng qiáng！ zhè de de bǎi xìng， nǐ men dōu dāng gāng qiáng zuò gōng， yīn wèi wǒ yǔ nǐ men tóng zài. zhè shì wàn jūn zhī yé hé huá shuō de."],[2,5,"這是 照着你們出 埃及我與你們立約的話。那時，我的靈住在你們中間，你們不要懼怕。」","zhè shì zhào zhe nǐ men chū āi jí wǒ yǔ nǐ men lì yuē de huà. nà shí， wǒ de líng zhù zài nǐ men zhōng jiān， nǐ men bù yào jù pà.’"],[2,6,"萬軍之耶和華如此說：「過不多時，我必再一次震動天地、滄海，與旱地。","wàn jūn zhī yé hé huá rú cǐ shuō：‘guò bù duō shí， wǒ bì zài yī cì zhèn dòng tiān de, cāng hǎi， yǔ hàn de."],[2,7,"我必震動萬國；萬國的珍寶必都運來，我就使這殿滿了榮耀。這是萬軍之耶和華說的。」","wǒ bì zhèn dòng wàn guó； wàn guó de zhēn bǎo bì dōu yùn lái， wǒ jiù shǐ zhè diàn mǎn le róng yào. zhè shì wàn jūn zhī yé hé huá shuō de.’"],[2,8,"萬軍之耶和華說：「銀子是我的，金子也是我的。","wàn jūn zhī yé hé huá shuō：‘yín zǐ shì wǒ de， jīn zǐ yě shì wǒ de."],[2,9,"這殿後來的榮耀必大過先前的榮耀；在這地方我必賜平安。這是萬軍之耶和華說的。」","zhè diàn hòu lái de róng yào bì dà guò xiān qián de róng yào； zài zhè de fāng wǒ bì cì píng ān. zhè shì wàn jūn zhī yé hé huá shuō de.’"],[2,10,"大流士王第二年九 月二十四 日，耶和華的話臨到先知 哈該說：","dà liú shì wáng dì èr nián jiǔ yuè èr shí sì rì， yé hé huá de huà lín dào xiān zhī hā gāi shuō："],[2,11,"萬軍之耶和華如此說：「你要向祭司問律法，","wàn jūn zhī yé hé huá rú cǐ shuō：‘nǐ yào xiàng jì sī wèn lǜ fǎ，"],[2,12,"說：若有人用衣襟兜聖肉，這衣襟挨着餅，或湯，或酒，或油，或別的食物，便算為聖嗎？」祭司說：「不算為聖。」","shuō： ruò yǒu rén yòng yī jīn dōu shèng ròu， zhè yī jīn āi zhe bǐng， huò tāng， huò jiǔ， huò yóu， huò bié de shí wù， biàn suàn wèi shèng ma？’ jì sī shuō：‘bù suàn wèi shèng.’"],[2,13,"哈該又說：「若有人因摸死屍染了污穢，然後挨着這些物的哪一樣，這物算污穢嗎？」祭司說：「必算污穢。」","hā gāi yòu shuō：‘ruò yǒu rén yīn mō sǐ shī rǎn le wū huì， rán hòu āi zhe zhè xiē wù de nǎ yī yàng， zhè wù suàn wū huì ma？’ jì sī shuō：‘bì suàn wū huì.’"],[2,14,"於是 哈該說：「耶和華說：這民這國，在我面前也是如此；他們手下的各樣工作都是如此；他們在壇上所獻的也是如此。」","yú shì hā gāi shuō：‘yé hé huá shuō： zhè mín zhè guó， zài wǒ miàn qián yě shì rú cǐ； tā men shǒu xià de gè yàng gōng zuò dōu shì rú cǐ； tā men zài tán shàng suǒ xiàn de yě shì rú cǐ.’"],[2,15,"現在你們要追想，此日以前，耶和華的殿沒有一塊石頭壘在石頭上的光景。","xiàn zài nǐ men yào zhuī xiǎng， cǐ rì yǐ qián， yé hé huá de diàn méi yǒu yī kuài shí tóu lěi zài shí tóu shàng de guāng jǐng."],[2,16,"在那一切日子，有人來到 穀堆，想得二十 斗，只得了十 斗。有人來到酒池，想得五十 桶，只得了二十 桶。","zài nà yī qiè rì zǐ， yǒu rén lái dào gǔ duī， xiǎng dé èr shí dòu， zhǐ dé le shí dòu. yǒu rén lái dào jiǔ chí， xiǎng dé wǔ shí tǒng， zhǐ dé le èr shí tǒng."],[2,17,"在你們手下的各樣工作上，我以旱風、霉爛、冰雹攻擊你們，你們仍不 歸向我。這是耶和華說的。","zài nǐ men shǒu xià de gè yàng gōng zuò shàng， wǒ yǐ hàn fēng, méi làn, bīng báo gōng jī nǐ men， nǐ men réng bù guī xiàng wǒ. zhè shì yé hé huá shuō de."],[2,18,"你們要追想此日以前，就是從這九月二十四日起，追想到立耶和華殿根基的日子。","nǐ men yào zhuī xiǎng cǐ rì yǐ qián， jiù shì cóng zhè jiǔ yuè èr shí sì rì qǐ， zhuī xiǎng dào lì yé hé huá diàn gēn jī de rì zǐ."],[2,19,"倉裏有穀種嗎？葡萄樹、無花果樹、石榴樹、橄欖樹都沒有結果子。從今日起，我必賜福 與你們。","cāng lǐ yǒu gǔ zhǒng ma？ pú táo shù, wú huā guǒ shù, shí liú shù, gǎn lǎn shù dōu méi yǒu jié guǒ zǐ. cóng jīn rì qǐ， wǒ bì cì fú yǔ nǐ men."],[2,20,"這月二十四日，耶和華的話二次臨到 哈該說：","zhè yuè èr shí sì rì， yé hé huá de huà èr cì lín dào hā gāi shuō："],[2,21,"「你要告訴 猶大省長 所羅巴伯說：我必震動天地。","‘nǐ yào gào sù yóu dà shěng zhǎng suǒ luó bā bó shuō： wǒ bì zhèn dòng tiān de."],[2,22,"我必傾覆列國的寶座，除滅列邦的勢力，並傾覆戰車和坐在其上的。馬必跌倒，騎馬的敗落，各人被弟兄的刀所殺。","wǒ bì qīng fù liè guó de bǎo zuò， chú miè liè bāng de shì lì， bìng qīng fù zhàn chē hé zuò zài qí shàng de. mǎ bì diē dào， qí mǎ de bài luò， gè rén bèi dì xiōng de dāo suǒ shā."],[2,23,"萬軍之耶和華說：我僕人 撒拉鐵的兒子 所羅巴伯啊，到那日，我必以你為印，因我揀選了你。這是萬軍之耶和華說的。」","wàn jūn zhī yé hé huá shuō： wǒ pú rén sā lā tiě de ér zǐ suǒ luó bā bó a， dào nà rì， wǒ bì yǐ nǐ wèi yìn， yīn wǒ jiǎn xuǎn le nǐ. zhè shì wàn jūn zhī yé hé huá shuō de.’"]],"arb-vandyck":[[1,1,"فِي ٱلسَّنَةِ ٱلثَّانِيَةِ لِدَارِيُوسَ ٱلْمَلِكِ، فِي ٱلشَّهْرِ ٱلسَّادِسِ فِي أَوَّلِ يَوْمٍ مِنَ ٱلشَّهْرِ، كَانَتْ كَلِمَةُ ٱلرَّبِّ عَنْ يَدِ حَجَّي ٱلنَّبِيِّ إِلَى زَرُبَّابِلَ بْنِ شَأَلْتِيئِيلَ وَالِي يَهُوذَا، وَإِلَى يَهُوشَعَ بْنِ يَهُوصَادِقَ ٱلْكَاهِنِ ٱلْعَظِيمِ قَائِلًا:","fī ٱlsãnaẗi ٱltẖãạnīaẗi lidārīūsa ٱl̊maliki, fī ٱlsẖãh̊ri ٱlsãạdisi fī ạảwãli yaẘmiⁿ mina ٱlsẖãh̊ri, kānat̊ kalimaẗu ٱlrãbĩ ʿan̊ yadi ḥajãy ٱlnãbīĩ ại̹lay̱ zarubãạbila b̊ni sẖāảl̊tīyỉyla wālī yahūdẖā, wāi̹lay̱ yahūsẖaʿa b̊ni yahūṣādiqa ٱl̊kāhini ٱl̊ʿaẓīmi qāyỉlaⁿạ:"],[1,2,"«هَكَذَا قَالَ رَبُّ ٱلْجُنُودِ قَائِلًا: هَذَا ٱلشَّعْبُ قَالَ إِنَّ ٱلْوَقْتَ لَمْ يَبْلُغْ وَقْتَ بِنَاءِ بَيْتِ ٱلرَّبِّ».","«hakadẖā qāla rabũ ٱl̊junūdi qāyỉlaⁿạ: hadẖā ٱlsẖãʿ̊bu qāla ại̹nã ٱl̊waq̊ta lam̊ yab̊lugẖ̊ waq̊ta bināʾi baẙti ٱlrãbĩ»."],[1,3,"فَكَانَتْ كَلِمَةُ ٱلرَّبِّ عَنْ يَدِ حَجَّي ٱلنَّبِيِّ قَائِلًا:","fakānat̊ kalimaẗu ٱlrãbĩ ʿan̊ yadi ḥajãy ٱlnãbīĩ qāyỉlaⁿạ:"],[1,4,"«هَلِ ٱلْوَقْتُ لَكُمْ أَنْتُمْ أَنْ تَسْكُنُوا فِي بُيُوتِكُمُ ٱلْمُغَشَّاةِ، وَهَذَا ٱلْبَيْتُ خَرَابٌ؟","«hali ٱl̊waq̊tu lakum̊ ạản̊tum̊ ạản̊ tas̊kunūạ fī buyūtikumu ٱl̊mugẖasẖãạẗi, wahadẖā ٱl̊baẙtu kẖarābuⁿ?"],[1,5,"وَٱلْآنَ فَهَكَذَا قَالَ رَبُّ ٱلْجُنُودِ: ٱجْعَلُوا قَلْبَكُمْ عَلَى طُرُقِكُمْ.","waٱl̊ậna fahakadẖā qāla rabũ ٱl̊junūdi: ٱj̊ʿalūạ qal̊bakum̊ ʿalay̱ ṭuruqikum̊."],[1,6,"زَرَعْتُمْ كَثِيرًا وَدَخَّلْتُمْ قَلِيلًا. تَأْكُلُونَ وَلَيْسَ إِلَى ٱلشَّبَعِ. تَشْرَبُونَ وَلَا تَرْوُونَ. تَكْتَسُونَ وَلَا تَدْفَأُونَ. وَٱلْآخِذُ أُجْرَةً يَأْخُذُ أُجْرَةً لِكِيسٍ مَنْقُوبٍ.","zaraʿ̊tum̊ katẖīraⁿạ wadakẖãl̊tum̊ qalīlaⁿạ. tā̊̉kulūna walaẙsa ại̹lay̱ ٱlsẖãbaʿi. tasẖ̊rabūna walā tar̊wūna. tak̊tasūna walā tad̊fāủwna. waٱl̊ậkẖidẖu ạủj̊raẗaⁿ yā̊̉kẖudẖu ạủj̊raẗaⁿ likīsiⁿ man̊qūbiⁿ."],[1,7,"«هَكَذَا قَالَ رَبُّ ٱلْجُنُودِ: ٱجْعَلُوا قَلْبَكُمْ عَلَى طُرُقِكُمْ.","«hakadẖā qāla rabũ ٱl̊junūdi: ٱj̊ʿalūạ qal̊bakum̊ ʿalay̱ ṭuruqikum̊."],[1,8,"اِصْعَدُوا إِلَى ٱلْجَبَلِ وَأْتُوا بِخَشَبٍ وَٱبْنُوا ٱلْبَيْتَ، فَأَرْضَى عَلَيْهِ وَأَتَمَجَّدَ، قَالَ ٱلرَّبُّ.","ạiṣ̊ʿadūạ ại̹lay̱ ٱl̊jabali wā̊̉tūạ bikẖasẖabiⁿ waٱb̊nūạ ٱl̊baẙta, fāảr̊ḍay̱ ʿalaẙhi wāảtamajãda, qāla ٱlrãbũ."],[1,9,"ٱنْتَظَرْتُمْ كَثِيرًا وَإِذَا هُوَ قَلِيلٌ. وَلَمَّا أَدْخَلْتُمُوهُ ٱلْبَيْتَ نَفَخْتُ عَلَيْهِ. لِمَاذَا؟ يَقُولُ رَبُّ ٱلْجُنُودِ. لِأَجْلِ بَيْتِي ٱلَّذِي هُوَ خَرَابٌ، وَأَنْتُمْ رَاكِضُونَ كُلُّ إِنْسَانٍ إِلَى بَيْتِهِ.","ٱn̊taẓar̊tum̊ katẖīraⁿạ wāi̹dẖā hūa qalīluⁿ. walamãạ ạảd̊kẖal̊tumūhu ٱl̊baẙta nafakẖ̊tu ʿalaẙhi. limādẖā? yaqūlu rabũ ٱl̊junūdi. liạảj̊li baẙtī ٱlãdẖī hūa kẖarābuⁿ, wāản̊tum̊ rākiḍūna kulũ ại̹n̊sāniⁿ ại̹lay̱ baẙtihi."],[1,10,"لِذَلِكَ مَنَعَتِ ٱلسَّمَاوَاتُ مِنْ فَوْقِكُمُ ٱلنَّدَى، وَمَنَعَتِ ٱلْأَرْضُ غَلَّتَهَا.","lidẖalika manaʿati ٱlsãmāwātu min̊ faẘqikumu ٱlnãday̱, wamanaʿati ٱl̊ạảr̊ḍu gẖalãtahā."],[1,11,"وَدَعَوْتُ بِٱلْحَرِّ عَلَى ٱلْأَرْضِ وَعَلَى ٱلْجِبَالِ وَعَلَى ٱلْحِنْطَةِ وَعَلَى ٱلْمِسْطَارِ وَعَلَى ٱلزَّيْتِ وَعَلَى مَا تُنْبِتُهُ ٱلْأَرْضُ، وَعَلَى ٱلنَّاسِ وَعَلَى ٱلْبَهَائِمِ، وَعَلَى كُلِّ أَتْعَابِ ٱلْيَدَيْنِ».","wadaʿaẘtu biٱl̊ḥarĩ ʿalay̱ ٱl̊ạảr̊ḍi waʿalay̱ ٱl̊jibāli waʿalay̱ ٱl̊ḥin̊ṭaẗi waʿalay̱ ٱl̊mis̊ṭāri waʿalay̱ ٱlzãẙti waʿalay̱ mā tun̊bituhu ٱl̊ạảr̊ḍu, waʿalay̱ ٱlnãạsi waʿalay̱ ٱl̊bahāyỉmi, waʿalay̱ kulĩ ạảt̊ʿābi ٱl̊yadaẙni»."],[1,12,"حِينَئِذٍ سَمِعَ زَرُبَّابِلُ بْنُ شَأَلْتِيئِيلَ وَيَهُوشَعُ بْنُ يَهُوصَادِقَ ٱلْكَاهِنِ ٱلْعَظِيمِ، وَكُلُّ بَقِيَّةِ ٱلشَّعْبِ صَوْتَ ٱلرَّبِّ إِلَهِهِمْ وَكَلَامَ حَجَّي ٱلنَّبِيِّ كَمَا أَرْسَلَهُ ٱلرَّبُّ إِلَهُهُمْ. وَخَافَ ٱلشَّعْبُ أَمَامَ وَجْهِ ٱلرَّبِّ.","ḥīnayỉdẖiⁿ samiʿa zarubãạbilu b̊nu sẖāảl̊tīyỉyla wayahūsẖaʿu b̊nu yahūṣādiqa ٱl̊kāhini ٱl̊ʿaẓīmi, wakulũ baqīãẗi ٱlsẖãʿ̊bi ṣaẘta ٱlrãbĩ ại̹lahihim̊ wakalāma ḥajãy ٱlnãbīĩ kamā ạảr̊salahu ٱlrãbũ ại̹lahuhum̊. wakẖāfa ٱlsẖãʿ̊bu ạảmāma waj̊hi ٱlrãbĩ."],[1,13,"فَقَالَ حَجَّي رَسُولُ ٱلرَّبِّ بِرِسَالَةِ ٱلرَّبِّ لِجَمِيعِ ٱلشَّعْبِ قَائِلًا: «أَنَا مَعَكُمْ، يَقُولُ ٱلرَّبُّ».","faqāla ḥajãy rasūlu ٱlrãbĩ birisālaẗi ٱlrãbĩ lijamīʿi ٱlsẖãʿ̊bi qāyỉlaⁿạ: «ạảnā maʿakum̊, yaqūlu ٱlrãbũ»."],[1,14,"وَنَبَّهَ ٱلرَّبُّ رُوحَ زَرُبَّابِلَ بْنِ شَأَلْتِيئِيلَ وَالِي يَهُوذَا، وَرُوحَ يَهُوشَعَ بْنِ يَهُوصَادِقَ ٱلْكَاهِنِ ٱلْعَظِيمِ، وَرُوحَ كُلِّ بَقِيَّةِ ٱلشَّعْبِ. فَجَاءُوا وَعَمِلُوا ٱلشُّغْلَ فِي بَيْتِ رَبِّ ٱلْجُنُودِ إِلَهِهِمْ،","wanabãha ٱlrãbũ rūḥa zarubãạbila b̊ni sẖāảl̊tīyỉyla wālī yahūdẖā, warūḥa yahūsẖaʿa b̊ni yahūṣādiqa ٱl̊kāhini ٱl̊ʿaẓīmi, warūḥa kulĩ baqīãẗi ٱlsẖãʿ̊bi. fajāʾūạ waʿamilūạ ٱlsẖũgẖ̊la fī baẙti rabĩ ٱl̊junūdi ại̹lahihim̊,"],[1,15,"فِي ٱلْيَوْمِ ٱلرَّابِعِ وَٱلْعِشْرِينَ مِنَ ٱلشَّهْرِ ٱلسَّادِسِ، فِي ٱلسَّنَةِ ٱلثَّانِيَةِ لِدَارِيُوسَ ٱلْمَلِكِ.","fī ٱl̊yaẘmi ٱlrãạbiʿi waٱl̊ʿisẖ̊rīna mina ٱlsẖãh̊ri ٱlsãạdisi, fī ٱlsãnaẗi ٱltẖãạnīaẗi lidārīūsa ٱl̊maliki."],[2,1,"فِي ٱلشَّهْرِ ٱلسَّابِعِ فِي ٱلْحَادِي وَٱلْعِشْرِينَ مِنَ ٱلشَّهْرِ، كَانَتْ كَلِمَةُ ٱلرَّبِّ عَنْ يَدِ حَجَّي ٱلنَّبِيِّ قَائِلًا:","fī ٱlsẖãh̊ri ٱlsãạbiʿi fī ٱl̊ḥādī waٱl̊ʿisẖ̊rīna mina ٱlsẖãh̊ri, kānat̊ kalimaẗu ٱlrãbĩ ʿan̊ yadi ḥajãy ٱlnãbīĩ qāyỉlaⁿạ:"],[2,2,"«كَلِّمْ زَرُبَّابِلَ بْنَ شَأَلْتِيئِيلَ وَالِيَ يَهُوذَا، وَيَهُوشَعَ بْنِ يَهُوصَادِقَ ٱلْكَاهِنِ ٱلْعَظِيمِ وَبَقِيَّةِ ٱلشَّعْبِ قَائِلًا:","«kalĩm̊ zarubãạbila b̊na sẖāảl̊tīyỉyla wālīa yahūdẖā, wayahūsẖaʿa b̊ni yahūṣādiqa ٱl̊kāhini ٱl̊ʿaẓīmi wabaqīãẗi ٱlsẖãʿ̊bi qāyỉlaⁿạ:"],[2,3,"مَنِ ٱلْبَاقِي فِيكُمُ ٱلَّذِي رَأَى هَذَا ٱلْبَيْتَ فِي مَجْدِهِ ٱلْأَوَّلِ؟ وَكَيْفَ تَنْظُرُونَهُ ٱلْآنَ؟ أَمَا هُوَ فِي أَعْيُنِكُمْ كَلَا شَيْءٍ!","mani ٱl̊bāqī fīkumu ٱlãdẖī rāảy̱ hadẖā ٱl̊baẙta fī maj̊dihi ٱl̊ạảwãli? wakaẙfa tan̊ẓurūnahu ٱl̊ậna? ạảmā hūa fī ạảʿ̊yunikum̊ kalā sẖaẙʾiⁿ!"],[2,4,"فَٱلْآنَ تَشَدَّدْ يَا زَرُبَّابِلُ، يَقُولُ ٱلرَّبُّ. وَتَشَدَّدْ يَا يَهُوشَعُ بْنُ يَهُوصَادِقَ ٱلْكَاهِنُ ٱلْعَظِيمُ، وَتَشَدَّدُوا يَا جَمِيعَ شَعْبِ ٱلْأَرْضِ، يَقُولُ ٱلرَّبُّ. وَٱعْمَلُوا فَإِنِّي مَعَكُمْ، يَقُولُ رَبُّ ٱلْجُنُودِ.","faٱl̊ậna tasẖadãd̊ yā zarubãạbilu, yaqūlu ٱlrãbũ. watasẖadãd̊ yā yahūsẖaʿu b̊nu yahūṣādiqa ٱl̊kāhinu ٱl̊ʿaẓīmu, watasẖadãdūạ yā jamīʿa sẖaʿ̊bi ٱl̊ạảr̊ḍi, yaqūlu ٱlrãbũ. waٱʿ̊malūạ fāi̹nĩy maʿakum̊, yaqūlu rabũ ٱl̊junūdi."],[2,5,"حَسَبَ ٱلْكَلَامِ ٱلَّذِي عَاهَدْتُكُمْ بِهِ عِنْدَ خُرُوجِكُمْ مِنْ مِصْرَ، وَرُوحِي قَائِمٌ فِي وَسَطِكُمْ. لَا تَخَافُوا.","ḥasaba ٱl̊kalāmi ٱlãdẖī ʿāhad̊tukum̊ bihi ʿin̊da kẖurūjikum̊ min̊ miṣ̊ra, warūḥī qāyỉmuⁿ fī wasaṭikum̊. lā takẖāfūạ."],[2,6,"لِأَنَّهُ هَكَذَا قَالَ رَبُّ ٱلْجُنُودِ: هِيَ مَرَّةٌ، بَعْدَ قَلِيلٍ، فَأُزَلْزِلُ ٱلسَّمَاوَاتِ وَٱلْأَرْضَ وَٱلْبَحْرَ وَٱلْيَابِسَةَ،","liạảnãhu hakadẖā qāla rabũ ٱl̊junūdi: hīa marãẗuⁿ, baʿ̊da qalīliⁿ, fāủzal̊zilu ٱlsãmāwāti waٱl̊ạảr̊ḍa waٱl̊baḥ̊ra waٱl̊yābisaẗa,"],[2,7,"وَأُزَلْزِلُ كُلَّ ٱلْأُمَمِ. وَيَأْتِي مُشْتَهَى كُلِّ ٱلْأُمَمِ، فَأَمْلَأُ هَذَا ٱلْبَيْتَ مَجْدًا، قَالَ رَبُّ ٱلْجُنُودِ.","wāủzal̊zilu kulã ٱl̊ạủmami. wayā̊̉tī musẖ̊tahay̱ kulĩ ٱl̊ạủmami, fāảm̊lāủ hadẖā ٱl̊baẙta maj̊daⁿạ, qāla rabũ ٱl̊junūdi."],[2,8,"لِي ٱلْفِضَّةُ وَلِي ٱلذَّهَبُ، يَقُولُ رَبُّ ٱلْجُنُودِ.","lī ٱl̊fiḍãẗu walī ٱldẖãhabu, yaqūlu rabũ ٱl̊junūdi."],[2,9,"مَجْدُ هَذَا ٱلْبَيْتِ ٱلْأَخِيرِ يَكُونُ أَعْظَمَ مِنْ مَجْدِ ٱلْأَوَّلِ، قَالَ رَبُّ ٱلْجُنُودِ. وَفِي هَذَا ٱلْمَكَانِ أُعْطِي ٱلسَّلَامَ، يَقُولُ رَبُّ ٱلْجُنُودِ».","maj̊du hadẖā ٱl̊baẙti ٱl̊ạảkẖīri yakūnu ạảʿ̊ẓama min̊ maj̊di ٱl̊ạảwãli, qāla rabũ ٱl̊junūdi. wafī hadẖā ٱl̊makāni ạủʿ̊ṭī ٱlsãlāma, yaqūlu rabũ ٱl̊junūdi»."],[2,10,"فِي ٱلرَّابِعِ وَٱلْعِشْرِينَ مِنَ ٱلشَّهْرِ ٱلتَّاسِعِ، فِي ٱلسَّنَةِ ٱلثَّانِيَةِ لِدَارِيُوسَ، كَانَتْ كَلِمَةُ ٱلرَّبِّ عَنْ يَدِ حَجَّي ٱلنَّبِيِّ قَائِلًا:","fī ٱlrãạbiʿi waٱl̊ʿisẖ̊rīna mina ٱlsẖãh̊ri ٱltãạsiʿi, fī ٱlsãnaẗi ٱltẖãạnīaẗi lidārīūsa, kānat̊ kalimaẗu ٱlrãbĩ ʿan̊ yadi ḥajãy ٱlnãbīĩ qāyỉlaⁿạ:"],[2,11,"«هَكَذَا قَالَ رَبُّ ٱلْجُنُودِ: اِسْأَلِ ٱلْكَهَنَةَ عَنِ ٱلشَّرِيعَةِ قَائِلًا:","«hakadẖā qāla rabũ ٱl̊junūdi: ạis̊ạảli ٱl̊kahanaẗa ʿani ٱlsẖãrīʿaẗi qāyỉlaⁿạ:"],[2,12,"إِنْ حَمَلَ إِنْسَانٌ لَحْمًا مُقَدَّسًا فِي طَرَفِ ثَوْبِهِ وَمَسَّ بِطَرَفِهِ خُبْزًا أَوْ طَبِيخًا أَوْ خَمْرًا أَوْ زَيْتًا أَوْ طَعَامًا مَّا، فَهَلْ يَتَقَدَّسُ؟» فَأَجَابَ ٱلْكَهَنَةُ وَقَالُوا: «لَا».","ại̹n̊ ḥamala ại̹n̊sānuⁿ laḥ̊maⁿạ muqadãsaⁿạ fī ṭarafi tẖaẘbihi wamasã biṭarafihi kẖub̊zaⁿạ ạảẘ ṭabīkẖaⁿạ ạảẘ kẖam̊raⁿạ ạảẘ zaẙtaⁿạ ạảẘ ṭaʿāmaⁿạ mãạ, fahal̊ yataqadãsu?» fāảjāba ٱl̊kahanaẗu waqālūạ: «lā»."],[2,13,"فَقَالَ حَجَّي: «إِنْ كَانَ ٱلْمُنَجَّسُ بِمَيْتٍ يَمَسُّ شَيْئًا مِنْ هَذِهِ، فَهَلْ يَتَنَجَّسُ؟» فَأَجَابَ ٱلْكَهَنَةُ وَقَالُوا: «يَتَنَجَّسُ».","faqāla ḥajãy: «ại̹n̊ kāna ٱl̊munajãsu bimaẙtiⁿ yamasũ sẖaẙyaⁿ̉ạ min̊ hadẖihi, fahal̊ yatanajãsu?» fāảjāba ٱl̊kahanaẗu waqālūạ: «yatanajãsu»."],[2,14,"فَأَجَابَ حَجَّي وَقَالَ: «هَكَذَا هَذَا ٱلشَّعْبُ، وَهَكَذَا هَذِهِ ٱلْأُمَّةُ قُدَّامِي، يَقُولُ ٱلرَّبُّ، وَهَكَذَا كُلُّ عَمَلِ أَيْدِيهِمْ وَمَا يُقَرِّبُونَهُ هُنَاكَ. هُوَ نَجِسٌ.","fāảjāba ḥajãy waqāla: «hakadẖā hadẖā ٱlsẖãʿ̊bu, wahakadẖā hadẖihi ٱl̊ạủmãẗu qudãạmī, yaqūlu ٱlrãbũ, wahakadẖā kulũ ʿamali ạảẙdīhim̊ wamā yuqarĩbūnahu hunāka. hūa najisuⁿ."],[2,15,"وَٱلْآنَ فَٱجْعَلُوا قَلْبَكُمْ مِنْ هَذَا ٱلْيَوْمِ فَرَاجِعًا، قَبْلَ وَضْعِ حَجَرٍ عَلَى حَجَرٍ فِي هَيْكَلِ ٱلرَّبِّ.","waٱl̊ậna faٱj̊ʿalūạ qal̊bakum̊ min̊ hadẖā ٱl̊yaẘmi farājiʿaⁿạ, qab̊la waḍ̊ʿi ḥajariⁿ ʿalay̱ ḥajariⁿ fī haẙkali ٱlrãbĩ."],[2,16,"مُذْ تِلْكَ ٱلْأَيَّامِ كَانَ أَحَدُكُمْ يَأْتِي إِلَى عَرَمَةِ عِشْرِينَ فَكَانَتْ عَشَرَةً. أَتَى إِلَى حَوْضِ ٱلْمِعْصَرَةِ لِيَغْرُفَ خَمْسِينَ فُورَةً فَكَانَتْ عِشْرِينَ.","mudẖ̊ til̊ka ٱl̊ạảyãạmi kāna ạảḥadukum̊ yā̊̉tī ại̹lay̱ ʿaramaẗi ʿisẖ̊rīna fakānat̊ ʿasẖaraẗaⁿ. ạảtay̱ ại̹lay̱ ḥaẘḍi ٱl̊miʿ̊ṣaraẗi līagẖ̊rufa kẖam̊sīna fūraẗaⁿ fakānat̊ ʿisẖ̊rīna."],[2,17,"قَدْ ضَرَبْتُكُمْ بِٱللَّفْحِ وَبِالْيَرَقَانِ وَبِالْبَرَدِ فِي كُلِّ عَمَلِ أَيْدِيكُمْ، وَمَا رَجَعْتُمْ إِلَيَّ، يَقُولُ ٱلرَّبُّ.","qad̊ ḍarab̊tukum̊ biٱllãf̊ḥi wabiạl̊yaraqāni wabiạl̊baradi fī kulĩ ʿamali ạảẙdīkum̊, wamā rajaʿ̊tum̊ ại̹layã, yaqūlu ٱlrãbũ."],[2,18,"فَٱجْعَلُوا قَلْبَكُمْ مِنْ هَذَا ٱلْيَوْمِ فَصَاعِدًا، مِنَ ٱلْيَوْمِ ٱلرَّابِعِ وَٱلْعِشْرِينَ مِنَ ٱلشَّهْرِ ٱلتَّاسِعِ، مِنَ ٱلْيَوْمِ ٱلَّذِي فِيهِ تَأَسَّسَ هَيْكَلُ ٱلرَّبِّ، ٱجْعَلُوا قَلْبَكُمْ.","faٱj̊ʿalūạ qal̊bakum̊ min̊ hadẖā ٱl̊yaẘmi faṣāʿidaⁿạ, mina ٱl̊yaẘmi ٱlrãạbiʿi waٱl̊ʿisẖ̊rīna mina ٱlsẖãh̊ri ٱltãạsiʿi, mina ٱl̊yaẘmi ٱlãdẖī fīhi tāảsãsa haẙkalu ٱlrãbĩ, ٱj̊ʿalūạ qal̊bakum̊."],[2,19,"هَلِ ٱلْبَذْرُ فِي ٱلْأَهْرَاءِ بَعْدُ؟ وَٱلْكَرْمُ وَٱلتِّينُ وَٱلرُّمَّانُ وَٱلزَّيْتُونُ لَمْ يَحْمِلْ بَعْدُ. فَمِنْ هَذَا ٱلْيَوْمِ أُبَارِكُ».","hali ٱl̊badẖ̊ru fī ٱl̊ạảh̊rāʾi baʿ̊du? waٱl̊kar̊mu waٱltĩynu waٱlrũmãạnu waٱlzãẙtūnu lam̊ yaḥ̊mil̊ baʿ̊du. famin̊ hadẖā ٱl̊yaẘmi ạủbāriku»."],[2,20,"وَصَارَتْ كَلِمَةُ ٱلرَّبِّ ثَانِيَةً إِلَى حَجَّي، فِي ٱلرَّابِعِ وَٱلْعِشْرِينَ مِنَ ٱلشَّهْرِ قَائِلًا:","waṣārat̊ kalimaẗu ٱlrãbĩ tẖānīaẗaⁿ ại̹lay̱ ḥajãy, fī ٱlrãạbiʿi waٱl̊ʿisẖ̊rīna mina ٱlsẖãh̊ri qāyỉlaⁿạ:"],[2,21,"«كَلِّمْ زَرُبَّابِلَ وَالِيَ يَهُوذَا قَائِلًا: إِنِّي أُزَلْزِلُ ٱلسَّمَاوَاتِ وَٱلْأَرْضَ،","«kalĩm̊ zarubãạbila wālīa yahūdẖā qāyỉlaⁿạ: ại̹nĩy ạủzal̊zilu ٱlsãmāwāti waٱl̊ạảr̊ḍa,"],[2,22,"وَأَقْلِبُ كُرْسِيَّ ٱلْمَمَالِكِ، وَأُبِيدُ قُوَّةَ مَمَالِكِ ٱلْأُمَمِ، وَأَقْلِبُ ٱلْمَرْكَبَاتِ وَٱلرَّاكِبِينَ فِيهَا، وَيَنْحَطُّ ٱلْخَيْلُ وَرَاكِبُوهَا، كُلٌّ مِنْهَا بِسَيْفِ أَخِيهِ.","wāảq̊libu kur̊sīã ٱl̊mamāliki, wāủbīdu qūãẗa mamāliki ٱl̊ạủmami, wāảq̊libu ٱl̊mar̊kabāti waٱlrãạkibīna fīhā, wayan̊ḥaṭũ ٱl̊kẖaẙlu warākibūhā, kuluⁿ̃ min̊hā bisaẙfi ạảkẖīhi."],[2,23,"فِي ذَلِكَ ٱلْيَوْمِ، يَقُولُ رَبُّ ٱلْجُنُودِ، آخُذُكَ يَا زَرُبَّابِلُ عَبْدِي ٱبْنُ شَأَلْتِيئِيلَ، يَقُولُ ٱلرَّبُّ، وَأَجْعَلُكَ كَخَاتِمٍ، لِأَنِّي قَدِ ٱخْتَرْتُكَ، يَقُولُ رَبُّ ٱلْجُنُودِ».","fī dẖalika ٱl̊yaẘmi, yaqūlu rabũ ٱl̊junūdi, ậkẖudẖuka yā zarubãạbilu ʿab̊dī ٱb̊nu sẖāảl̊tīyỉyla, yaqūlu ٱlrãbũ, wāảj̊ʿaluka kakẖātimiⁿ, liạảnĩy qadi ٱkẖ̊tar̊tuka, yaqūlu rabũ ٱl̊junūdi»."]],"bis-obbr":[[1,1,"Long namba tu yia we Darias i king* long Pesia, long namba sikis manis*, long fas dei blong hem, Hae God i givim tok blong hem long Profet Hagae, blong hem i go talemaot long Serubabel we i distrikejen* blong Juda*, mo long Josua we i hae pris*. Serubabel ya, papa blong hem Sealtiel, mo Josua ya, papa blong hem Jehosadak.","Long namba tu yia we Darias i king* long Pesia, long namba sikis manis*, long fas dei blong hem, Hae God i givim tok blong hem long Profet Hagae, blong hem i go talemaot long Serubabel we i distrikejen* blong Juda*, mo long Josua we i hae pris*. Serubabel ya, papa blong hem Sealtiel, mo Josua ya, papa blong hem Jehosadak."],[1,2,"Nao Profet Hagae i talem se, “Hae God i gat olgeta paoa, mo hem i talem se, ‘Ol man ya oli stap talem se i no taem yet blong wokem haos* blong mi bakegen.’ ”","Nao Profet Hagae i talem se, “Hae God i gat olgeta paoa, mo hem i talem se, ‘Ol man ya oli stap talem se i no taem yet blong wokem haos* blong mi bakegen.’ ”"],[1,3,"Mo profet i go talemaot long ol man we Hae God i talem se,","Mo profet i go talemaot long ol man we Hae God i talem se,"],[1,4,"“Ol man blong mi. ?From wanem yufala i stap slip long ol gudgudfala haos, be haos blong mi i stap we i nogud yet?","“Ol man blong mi. ?From wanem yufala i stap slip long ol gudgudfala haos, be haos blong mi i stap we i nogud yet?"],[1,5,"?Ating yufala i no luksave samting ya we i stap kasem yufala?","?Ating yufala i no luksave samting ya we i stap kasem yufala?"],[1,6,"Yufala i stap planem plante kakae long ol garen blong yufala, be smol kakae nomo i stap kamaot long hem. Yufala i stap kakae, be kakae ya i no naf long yufala. Yufala i stap dring waen, be waen ya tu i no naf blong mekem yufala i harem gud long hem. Yufala i gat klos blong yufala, be ol klos ya i no naf blong mekem yufala i wom. Mo man blong wok i stap wok had blong kasem mane, be mane ya we i stap kasem i no naf blong holem hem, from we oltaem nomo poket i stap brok.","Yufala i stap planem plante kakae long ol garen blong yufala, be smol kakae nomo i stap kamaot long hem. Yufala i stap kakae, be kakae ya i no naf long yufala. Yufala i stap dring waen, be waen ya tu i no naf blong mekem yufala i harem gud long hem. Yufala i gat klos blong yufala, be ol klos ya i no naf blong mekem yufala i wom. Mo man blong wok i stap wok had blong kasem mane, be mane ya we i stap kasem i no naf blong holem hem, from we oltaem nomo poket i stap brok."],[1,7,"?Olsem wanem? ?Yufala i no luksave ol samting ya we i stap kasem yufala?","?Olsem wanem? ?Yufala i no luksave ol samting ya we i stap kasem yufala?"],[1,8,"Naoia yufala i mas go long bus, yufala i katem ol timba, yufala i kam wokem haos blong mi bakegen, blong bambae mi save harem gud long hem. Mo yufala i save mekem wosip long mi bakegen, long fasin we mi mi glad long hem.","Naoia yufala i mas go long bus, yufala i katem ol timba, yufala i kam wokem haos blong mi bakegen, blong bambae mi save harem gud long hem. Mo yufala i save mekem wosip long mi bakegen, long fasin we mi mi glad long hem."],[1,9,"“Oltaem yufala i stap wet se bambae yufala i kasem plante kakae long ol garen blong yufala, be smol kakae nomo i stap kamaot long olgeta. Taem yufala i stap tekem ol kakae ya i kam long haos blong yufala, mi mi stap mekem win i blu long hem, nao ol kakae ya i lus. ?Yufala i ting se mi mekem olsem from wanem? Mi mekem olsem from we yufala i stap hadwok blong wokem ol haos blong yufala, be haos blong mi i stap we i nogud yet.","“Oltaem yufala i stap wet se bambae yufala i kasem plante kakae long ol garen blong yufala, be smol kakae nomo i stap kamaot long olgeta. Taem yufala i stap tekem ol kakae ya i kam long haos blong yufala, mi mi stap mekem win i blu long hem, nao ol kakae ya i lus. ?Yufala i ting se mi mekem olsem from wanem? Mi mekem olsem from we yufala i stap hadwok blong wokem ol haos blong yufala, be haos blong mi i stap we i nogud yet."],[1,10,"Nao from samting ya, mi mi no stap sanem ren i kam blong mekem ol garen blong yufala i gru gud.","Nao from samting ya, mi mi no stap sanem ren i kam blong mekem ol garen blong yufala i gru gud."],[1,11,"Mi mi letem finis blong olgeta ples long kantri blong yufala oli drae evriwan. Olgeta ples antap long hil, mo ol ples blong wokem garen, mo ol plantesen blong grep*, mo ol plantesen blong ol tri ya olif* oli drae evriwan. Trabol ya i kasem ol man mo ol anamol, mo i kasem olgeta samting we yufala i stap wok long hem.”","Mi mi letem finis blong olgeta ples long kantri blong yufala oli drae evriwan. Olgeta ples antap long hil, mo ol ples blong wokem garen, mo ol plantesen blong grep*, mo ol plantesen blong ol tri ya olif* oli drae evriwan. Trabol ya i kasem ol man mo ol anamol, mo i kasem olgeta samting we yufala i stap wok long hem.”"],[1,12,"Nao Serubabel mo Hae Pris* ya Josua mo olgeta man ya we oli bin stap wok slef* long Babilonia nao oli kambak, oli mekem samting ya we Hae God we i God blong olgeta i talem. Olgeta ya, oli fraet, nao oli obei long ol tok ya blong hem we Profet Hagae i talemaot.","Nao Serubabel mo Hae Pris* ya Josua mo olgeta man ya we oli bin stap wok slef* long Babilonia nao oli kambak, oli mekem samting ya we Hae God we i God blong olgeta i talem. Olgeta ya, oli fraet, nao oli obei long ol tok ya blong hem we Profet Hagae i talemaot."],[1,13,"Nao profet i talemaot bakegen long ol man ya we Hae God i talem se, “Mi bambae mi stap wetem yufala.”","Nao profet i talemaot bakegen long ol man ya we Hae God i talem se, “Mi bambae mi stap wetem yufala.”"],[1,14,"Hae God i gat olgeta paoa, nao hem i givim gudfala tingting long olgeta blong oli wokem bakegen haos* blong hem. Nao long namba tu yia blong King Darias, long namba sikis manis* blong yia ya, long namba twanti fo dei blong hem, olgeta ya oli statem wok blong haos ya bakegen.","Hae God i gat olgeta paoa, nao hem i givim gudfala tingting long olgeta blong oli wokem bakegen haos* blong hem. Nao long namba tu yia blong King Darias, long namba sikis manis* blong yia ya, long namba twanti fo dei blong hem, olgeta ya oli statem wok blong haos ya bakegen.",15],[2,1,"Long sem yia ya, we i namba tu yia we Darias i king, long namba seven manis*, long namba twanti wan dei blong hem, Hae God i toktok bakegen long Profet Hagae.","Long sem yia ya, we i namba tu yia we Darias i king, long namba seven manis*, long namba twanti wan dei blong hem, Hae God i toktok bakegen long Profet Hagae."],[2,2,"Hem i sanem profet ya blong i go luk Serubabel we i distrikejen* blong Juda*, mo Hae Pris* ya Josua, mo olgeta man, blong i talemaot tok blong hem long olgeta.","Hem i sanem profet ya blong i go luk Serubabel we i distrikejen* blong Juda*, mo Hae Pris* ya Josua, mo olgeta man, blong i talemaot tok blong hem long olgeta."],[2,3,"Nao profet i talem long olgeta ya se, “Hae God i gat olgeta paoa, mo hem i talem se, ‘?Ating i gat sam long yufala long ples ya, we oli save tingbaot yet haos* ya blong mi bifo we i flas we i flas gud? ?Naoia yufala i luk se i olsem wanem? ?Ating yufala i luk se hemia we yufala i stap wokem naoia, bambae i no gudwan olsem hemia blong fastaem?","Nao profet i talem long olgeta ya se, “Hae God i gat olgeta paoa, mo hem i talem se, ‘?Ating i gat sam long yufala long ples ya, we oli save tingbaot yet haos* ya blong mi bifo we i flas we i flas gud? ?Naoia yufala i luk se i olsem wanem? ?Ating yufala i luk se hemia we yufala i stap wokem naoia, bambae i no gudwan olsem hemia blong fastaem?"],[2,4,"Be yufala i no mas harem nogud from samting ya. Mi wantem se yufala evriwan i mas wok, from we mi mi stap wetem yufala.","Be yufala i no mas harem nogud from samting ya. Mi wantem se yufala evriwan i mas wok, from we mi mi stap wetem yufala."],[2,5,"Bifo, taem ol olfala bubu blong yufala oli aot long Ijip, mi mi mekem promes* wetem olgeta long taem ya, se oltaem bambae mi stap wetem olgeta, mo wetem olgeta we bambae oli stap kamaot biaen long olgeta. Mo kam kasem tede, mi stap yet wetem yufala. From samting ya i gud yufala i no fraet.","Bifo, taem ol olfala bubu blong yufala oli aot long Ijip, mi mi mekem promes* wetem olgeta long taem ya, se oltaem bambae mi stap wetem olgeta, mo wetem olgeta we bambae oli stap kamaot biaen long olgeta. Mo kam kasem tede, mi stap yet wetem yufala. From samting ya i gud yufala i no fraet."],[2,6,"“ ‘Mi mi Hae God, mi gat olgeta paoa, mo mi talem long yufala, se bambae i no longtaem, mi mekem heven mo wol ya mo solwota, olgeta evriwan i seksek.","“ ‘Mi mi Hae God, mi gat olgeta paoa, mo mi talem long yufala, se bambae i no longtaem, mi mekem heven mo wol ya mo solwota, olgeta evriwan i seksek."],[2,7,"Bambae mi winim olgeta narafala kantri, nao mi tekemaot ol gudgudfala samting blong olgeta, mi karem i kam, mi fulumap haos ya long hem.","Bambae mi winim olgeta narafala kantri, nao mi tekemaot ol gudgudfala samting blong olgeta, mi karem i kam, mi fulumap haos ya long hem."],[2,8,"Olgeta silva mo gol we i stap long wol ya oli blong mi.","Olgeta silva mo gol we i stap long wol ya oli blong mi."],[2,9,"Niufala haos ya blong mi bambae i flas we i flas gud, i winim hemia blong fastaem. Yufala i man blong mi, mo bambae mi mekem we yufala i gat plante samting, mo bambae yufala i gat pis. Mi mi Hae God, mi gat olgeta paoa, mo hemia tok blong mi.’ ”","Niufala haos ya blong mi bambae i flas we i flas gud, i winim hemia blong fastaem. Yufala i man blong mi, mo bambae mi mekem we yufala i gat plante samting, mo bambae yufala i gat pis. Mi mi Hae God, mi gat olgeta paoa, mo hemia tok blong mi.’ ”"],[2,10,"Long sem yia ya bakegen, long namba naen manis*, long namba twanti fo dei blong hem, Hae God i toktok bakegen long Profet Hagae, i talem se,","Long sem yia ya bakegen, long namba naen manis*, long namba twanti fo dei blong hem, Hae God i toktok bakegen long Profet Hagae, i talem se,"],[2,11,"“Yu go faenemaot long ol pris* se loa i talem olsem wanem.","“Yu go faenemaot long ol pris* se loa i talem olsem wanem."],[2,12,"Yu askem long olgeta se, ‘?Olsem wanem? ?Sipos wan long yufala i katemaot wan pis mit long mit ya we i blong bonem blong mekem sakrefaes, nao hem i karem mit ya long klos blong hem, mo klos ya i kasem wan bred*, no i kasem kakae we i dan finis, no i kasem waen, no olifoel* no sam narafala samting olsem, bambae samting ya i kam tabu?’ ” Taem hem i askem kwestin ya long olgeta, oli talem se, “Nogat.”","Yu askem long olgeta se, ‘?Olsem wanem? ?Sipos wan long yufala i katemaot wan pis mit long mit ya we i blong bonem blong mekem sakrefaes, nao hem i karem mit ya long klos blong hem, mo klos ya i kasem wan bred*, no i kasem kakae we i dan finis, no i kasem waen, no olifoel* no sam narafala samting olsem, bambae samting ya i kam tabu?’ ” Taem hem i askem kwestin ya long olgeta, oli talem se, “Nogat.”"],[2,13,"Nao Hagae i talem se, “Taem wan man i tajem bodi blong wan dedman, yufala i save wantaem se man ya i kam doti long fes blong God. ?Nao sipos man ya i go tajem wan long ol kakae ya, kakae ya bambae i kam doti no olsem wanem?” Ol pris oli talem se, “Yes, i mas kam doti.”","Nao Hagae i talem se, “Taem wan man i tajem bodi blong wan dedman, yufala i save wantaem se man ya i kam doti long fes blong God. ?Nao sipos man ya i go tajem wan long ol kakae ya, kakae ya bambae i kam doti no olsem wanem?” Ol pris oli talem se, “Yes, i mas kam doti.”"],[2,14,"Nao Hagae i talemaot we Hae God i talem se, “Hemia nao, i sem mak long yufala ol man blong ples ya, mo long olgeta samting we yufala i stap mekem, mo long olgeta sakrefaes we yufala i stap bonem blong givim i kam long mi. Olgeta evriwan i doti long fes blong mi.”","Nao Hagae i talemaot we Hae God i talem se, “Hemia nao, i sem mak long yufala ol man blong ples ya, mo long olgeta samting we yufala i stap mekem, mo long olgeta sakrefaes we yufala i stap bonem blong givim i kam long mi. Olgeta evriwan i doti long fes blong mi.”"],[2,15,"Nao Profet Hagae i talemaot we Hae God i talem se, “Olgeta. ?Ating yufala i no luksave ol samting ya we i stap kasem yufala naoia? Bifo, taem yufala i no stat yet blong wokem haos* blong mi bakegen,","Nao Profet Hagae i talemaot we Hae God i talem se, “Olgeta. ?Ating yufala i no luksave ol samting ya we i stap kasem yufala naoia? Bifo, taem yufala i no stat yet blong wokem haos* blong mi bakegen,"],[2,16,"oltaem, taem yufala i stap go blong tekemaot ol wit* mo bale* long ol garen blong yufala, yufala i stap ting se bambae yufala i kasem tu handred kilo, be yufala i stap kasem wan handred kilo nomo. Mo taem yufala i stap go blong tekem waen long ples blong hem, yufala i stap ting se bambae yufala i kasem wan handred lita, be yufala i stap kasem foti lita nomo.","oltaem, taem yufala i stap go blong tekemaot ol wit* mo bale* long ol garen blong yufala, yufala i stap ting se bambae yufala i kasem tu handred kilo, be yufala i stap kasem wan handred kilo nomo. Mo taem yufala i stap go blong tekem waen long ples blong hem, yufala i stap ting se bambae yufala i kasem wan handred lita, be yufala i stap kasem foti lita nomo."],[2,17,"Mi mi bin mekem ol ston blong aes* i folfoldaon long ol garen blong yufala, mo mi bin sanem strong win, mo sik blong kakae i kam long ples blong yufala blong spolem olgeta kakae long ol garen blong yufala. Be yufala i no tanem tingting blong yufala nating from ol sin blong yufala blong kambak long mi bakegen.","Mi mi bin mekem ol ston blong aes* i folfoldaon long ol garen blong yufala, mo mi bin sanem strong win, mo sik blong kakae i kam long ples blong yufala blong spolem olgeta kakae long ol garen blong yufala. Be yufala i no tanem tingting blong yufala nating from ol sin blong yufala blong kambak long mi bakegen."],[2,18,"Tede i namba twanti fo dei blong namba naen manis*, mo tede yufala i finisim fandesen blong haos ya blong mi. I stat naoia, bambae yufala i save luk wanem we bambae i kam long yufala.","Tede i namba twanti fo dei blong namba naen manis*, mo tede yufala i finisim fandesen blong haos ya blong mi. I stat naoia, bambae yufala i save luk wanem we bambae i kam long yufala."],[2,19,"Nating we ol kakae blong yufala i finis, mo ol rop blong grep*, mo ol figtri*, mo ol grenadin*, mo ol oliftri* blong yufala, oli no karem frut blong olgeta yet, be i stat naoia, bambae mi blesem yufala.”","Nating we ol kakae blong yufala i finis, mo ol rop blong grep*, mo ol figtri*, mo ol grenadin*, mo ol oliftri* blong yufala, oli no karem frut blong olgeta yet, be i stat naoia, bambae mi blesem yufala.”"],[2,20,"Nao long sem dei ya bakegen, Hae God i givim tok blong hem long Profet Hagae blong i go talemaot","Nao long sem dei ya bakegen, Hae God i givim tok blong hem long Profet Hagae blong i go talemaot"],[2,21,"long Serubabel, distrikejen* blong Juda* se, “Serubabel. I no longtaem, mi bambae mi mekem heven mo wol ya, tufala i seksek.","long Serubabel, distrikejen* blong Juda* se, “Serubabel. I no longtaem, mi bambae mi mekem heven mo wol ya, tufala i seksek."],[2,22,"Olgeta kantri we oli gat king blong olgeta, mi bambae mi spolem olgeta evriwan, mo bambae mi finisim paoa blong olgeta. Ol kat blong faet blong olgeta, mo ol man blong ron long ol kat ya, bambae mi kilim olgeta evriwan i ded. Ol hos blong olgeta, bambae mi kilim olgeta evriwan, mo ol man blong ron long ol hos ya bambae olgeta nomo oli kilkilim olgeta bakegen.","Olgeta kantri we oli gat king blong olgeta, mi bambae mi spolem olgeta evriwan, mo bambae mi finisim paoa blong olgeta. Ol kat blong faet blong olgeta, mo ol man blong ron long ol kat ya, bambae mi kilim olgeta evriwan i ded. Ol hos blong olgeta, bambae mi kilim olgeta evriwan, mo ol man blong ron long ol hos ya bambae olgeta nomo oli kilkilim olgeta bakegen."],[2,23,"Be yu Serubabel, long dei ya, bambae mi putumap yu, yu kam man blong wok blong mi, mo bambae mi mekem yu yu rul long nem blong mi. Mi mi jusumaot yu finis blong yu kam man blong mi. Mi mi Hae God, mi gat olgeta paoa, mo hemia tok blong mi.”","Be yu Serubabel, long dei ya, bambae mi putumap yu, yu kam man blong wok blong mi, mo bambae mi mekem yu yu rul long nem blong mi. Mi mi jusumaot yu finis blong yu kam man blong mi. Mi mi Hae God, mi gat olgeta paoa, mo hemia tok blong mi.”"]]}};